export interface RaveSlide {
  courseCode: string;
  order: number;
  title: string;
  type: 'text' | 'interactive' | 'knowledge-check';
  content: string;
  interactiveConfig?: Record<string, unknown>;
}

export const raveCourseContent: RaveSlide[] = [
// ============ FORM-CREATE (20 slides) ============
{ courseCode: 'FORM-CREATE', order: 1, title: 'Introduction to eCRF Builder', type: 'text', content: '<h2>eCRF Builder Overview</h2><p>The Form Builder lets you create electronic Case Report Forms (eCRFs) for your study. Each form collects data for a specific visit or assessment.</p><ul><li>Navigate: Sidebar → Forms → Create New Form</li><li>Forms have 4 tabs: Info, Design, Edit Checks, Preview</li><li>All changes require e-signature to publish</li></ul><img src="assets/sop-screenshots/sop-016/02_form_builder.png" alt="Form Builder">' },
{ courseCode: 'FORM-CREATE', order: 2, title: 'Creating a New Form — Info Tab', type: 'text', content: '<h2>Info Tab</h2><p>Start by setting form metadata:</p><table><tr><th>Field</th><th>Description</th></tr><tr><td>Form Name</td><td>Display name (e.g., "Demographics")</td></tr><tr><td>OID</td><td>Unique identifier (auto-generated)</td></tr><tr><td>Version</td><td>Semantic version (1.0.0)</td></tr><tr><td>Description</td><td>Purpose of this form</td></tr><tr><td>Category</td><td>Safety, Efficacy, or Administrative</td></tr></table>' },
{ courseCode: 'FORM-CREATE', order: 3, title: 'Design Tab — Adding Fields', type: 'text', content: '<h2>Design Tab & Quick Add</h2><p>The Design tab is your canvas. Use <strong>Quick Add</strong> to insert fields rapidly:</p><ol><li>Click "+ Add Field" or use keyboard shortcut (A)</li><li>Choose field type from the palette</li><li>Field appears at cursor position</li><li>Configure properties in the right panel</li></ol><p>Fields snap into sections. Drag to reorder.</p><img src="assets/sop-screenshots/sop-016/02_form_builder.png" alt="Design Tab">' },
{ courseCode: 'FORM-CREATE', order: 4, title: 'Field Types — Text, Number, Date', type: 'text', content: '<h2>Basic Field Types</h2><table><tr><th>Type</th><th>Use For</th><th>Options</th></tr><tr><td>Text</td><td>Names, comments, descriptions</td><td>Max length, pattern mask</td></tr><tr><td>Number</td><td>Vitals, lab values, measurements</td><td>Min/max, decimal places, unit</td></tr><tr><td>Date</td><td>Visit dates, onset dates</td><td>Format (DD-MMM-YYYY), partial allowed</td></tr></table><p>Tip: Use Number (not Text) for any value needing range checks.</p>' },
{ courseCode: 'FORM-CREATE', order: 5, title: 'Field Types — Choice Fields', type: 'text', content: '<h2>Choice Field Types</h2><table><tr><th>Type</th><th>Use For</th><th>Behavior</th></tr><tr><td>Dropdown</td><td>Long option lists (>5 items)</td><td>Single select, searchable</td></tr><tr><td>Radio</td><td>Short lists (2-5 items)</td><td>Single select, all visible</td></tr><tr><td>Checkbox</td><td>Multi-select items</td><td>Multiple selections allowed</td></tr></table><p>Define coded values for each option (e.g., "1=Male, 2=Female, 3=Other").</p>' },
{ courseCode: 'FORM-CREATE', order: 6, title: 'Field Types — Clinical Fields', type: 'text', content: '<h2>Specialized Clinical Fields</h2><ul><li><strong>Vital Signs:</strong> Pre-built template with BP, HR, Temp, RR, SpO2 — includes units and normal ranges</li><li><strong>Lab Values:</strong> Numeric with reference ranges, units, specimen type, abnormal flags</li><li><strong>Data Tables:</strong> Repeating rows for concomitant meds, adverse events — configurable columns</li></ul><p>These save time vs. building individual number fields.</p>' },
{ courseCode: 'FORM-CREATE', order: 7, title: 'Exercise: Create a Demographics Form', type: 'interactive', content: 'Create the basic fields for a Demographics CRF.', interactiveConfig: { type: 'fill-form', instruction: 'Configure these fields for a Demographics form. Choose the correct field type for each.', data: { fields: [{ label: 'Subject Initials — Field Type', type: 'select', correctAnswer: 'Text', options: ['Text', 'Number', 'Date', 'Dropdown'] }, { label: 'Date of Birth — Field Type', type: 'select', correctAnswer: 'Date', options: ['Text', 'Number', 'Date', 'Dropdown'] }, { label: 'Sex — Field Type', type: 'select', correctAnswer: 'Radio', options: ['Text', 'Radio', 'Checkbox', 'Number'] }, { label: 'Race — Field Type', type: 'select', correctAnswer: 'Checkbox', options: ['Radio', 'Dropdown', 'Checkbox', 'Text'] }] }, successMessage: 'Correct! Initials=Text, DOB=Date, Sex=Radio (few options), Race=Checkbox (multi-select).', hintMessage: 'Think about how many options each field has and whether multi-select is needed.' } },
{ courseCode: 'FORM-CREATE', order: 8, title: 'Configuring Field Properties', type: 'text', content: '<h2>Field Properties Panel</h2><p>Every field has configurable properties:</p><table><tr><th>Property</th><th>Purpose</th></tr><tr><td>Label</td><td>What the user sees</td></tr><tr><td>Variable Name</td><td>Database column (UPPERCASE, no spaces)</td></tr><tr><td>Required</td><td>Must be filled before submission</td></tr><tr><td>PHI</td><td>Marks as Protected Health Information</td></tr><tr><td>Help Text</td><td>Guidance shown on hover/focus</td></tr><tr><td>Default Value</td><td>Pre-populated value</td></tr></table>' },
{ courseCode: 'FORM-CREATE', order: 9, title: 'Exercise: Configure Field Properties', type: 'interactive', content: 'Set properties for a Blood Pressure field.', interactiveConfig: { type: 'fill-form', instruction: 'Configure the Systolic BP field with appropriate properties.', data: { fields: [{ label: 'Label', type: 'text', correctAnswer: 'any', placeholder: 'e.g., Systolic Blood Pressure' }, { label: 'Variable Name', type: 'text', correctAnswer: 'SYSBP', placeholder: 'UPPERCASE, no spaces', hint: 'Convention: short uppercase abbreviation' }, { label: 'Required?', type: 'select', correctAnswer: 'Yes', options: ['Yes', 'No'] }, { label: 'PHI?', type: 'select', correctAnswer: 'No', options: ['Yes', 'No'], hint: 'Is blood pressure personally identifiable?' }] }, successMessage: 'Good! BP values are required clinical data but not PHI (not personally identifiable).', hintMessage: 'PHI = data that can identify a specific person (names, DOB, MRN, etc.).' } },
{ courseCode: 'FORM-CREATE', order: 10, title: 'Sections and Grouping', type: 'text', content: '<h2>Organizing with Sections</h2><p>Sections group related fields visually and logically:</p><ul><li>Click "+ Add Section" to create a group</li><li>Drag fields into sections</li><li>Sections can be collapsible</li><li>Use for: Vitals, Demographics, Medical History, etc.</li></ul><p><strong>Multi-column layout:</strong> Set section to 2 or 3 columns for compact forms. Best for related short fields (e.g., BP systolic + diastolic side by side).</p>' },
{ courseCode: 'FORM-CREATE', order: 11, title: 'Exercise: Add Vital Signs Fields', type: 'interactive', content: 'Order the steps to add a Vital Signs section.', interactiveConfig: { type: 'order-steps', instruction: 'Arrange steps to add a complete Vital Signs section to your form.', data: { steps: [{ id: 's1', text: 'Click "+ Add Section" and name it "Vital Signs"' }, { id: 's2', text: 'Set section layout to 2-column' }, { id: 's3', text: 'Add Systolic BP field (Number, required)' }, { id: 's4', text: 'Add Diastolic BP field (Number, required)' }, { id: 's5', text: 'Add Heart Rate field (Number, required)' }, { id: 's6', text: 'Add Temperature field (Number) with unit selector' }], correctOrder: ['s1', 's2', 's3', 's4', 's5', 's6'] }, successMessage: 'Correct! Create section first, set layout, then add fields in logical order.' } },
{ courseCode: 'FORM-CREATE', order: 12, title: 'Edit Checks Tab', type: 'text', content: '<h2>Edit Checks Tab</h2><p>Add inline validation rules directly on the form:</p><ul><li><strong>Range checks:</strong> Systolic BP must be 60-260</li><li><strong>Required-if:</strong> If "Other" selected, specify field required</li><li><strong>Cross-field:</strong> Systolic must be > Diastolic</li><li><strong>Format:</strong> Date must be DD-MMM-YYYY</li></ul><p>These are quick checks. For complex rules, use the Validation Rules page (separate course).</p>' },
{ courseCode: 'FORM-CREATE', order: 13, title: 'Preview Tab', type: 'text', content: '<h2>Preview Tab</h2><p>Preview shows exactly how the form appears to data entry users:</p><ul><li>Test field rendering and layout</li><li>Verify section grouping looks correct</li><li>Check that help text displays properly</li><li>Confirm required field indicators (*) are visible</li><li>Test skip logic conditions (if configured)</li></ul><p>Always preview before publishing. Fixes are easy before publish, complex after.</p>' },
{ courseCode: 'FORM-CREATE', order: 14, title: 'Saving and Publishing', type: 'text', content: '<h2>Save vs. Publish</h2><table><tr><th>Action</th><th>Effect</th></tr><tr><td>Save Draft</td><td>Saves work — form not visible to data entry users</td></tr><tr><td>Publish</td><td>Makes form available — requires e-signature</td></tr></table><p>Publishing creates version 1.0.0. Future edits create new versions. Old versions remain for data already collected.</p>' },
{ courseCode: 'FORM-CREATE', order: 15, title: 'Versioning', type: 'text', content: '<h2>Form Versioning</h2><ul><li><strong>Major (2.0.0):</strong> Structural changes (fields added/removed)</li><li><strong>Minor (1.1.0):</strong> Label or help text changes</li><li><strong>Patch (1.0.1):</strong> Typo fixes only</li></ul><p>Data collected on v1.0 stays with v1.0. New patients get the latest version. Both versions coexist in the study.</p>' },
{ courseCode: 'FORM-CREATE', order: 16, title: 'Exercise: Publishing Workflow', type: 'interactive', content: 'Order the publish steps correctly.', interactiveConfig: { type: 'order-steps', instruction: 'Put the form publishing steps in correct order.', data: { steps: [{ id: 's1', text: 'Complete form design in Design tab' }, { id: 's2', text: 'Review in Preview tab' }, { id: 's3', text: 'Click Publish button' }, { id: 's4', text: 'Enter e-signature (username + password + reason)' }, { id: 's5', text: 'Form becomes available for data entry' }], correctOrder: ['s1', 's2', 's3', 's4', 's5'] }, successMessage: 'Correct! Preview before publish, then e-sign to confirm.' } },
{ courseCode: 'FORM-CREATE', order: 17, title: 'Knowledge Check: Form Structure', type: 'knowledge-check', content: 'Test your form building knowledge.', interactiveConfig: { sectionTitle: 'Form Structure', questions: [{ id: 'fc-1', question: 'Which field type allows selecting multiple options?', type: 'multiple-choice', options: ['Radio', 'Dropdown', 'Checkbox', 'Text'], correctIndex: 2, explanation: 'Checkbox allows multiple selections. Radio and Dropdown are single-select.' }, { id: 'fc-2', question: 'What does PHI mean on a field?', type: 'multiple-choice', options: ['Priority High Indicator', 'Protected Health Information', 'Primary Health Input', 'Patient History Index'], correctIndex: 1, explanation: 'PHI = Protected Health Information — data that can identify a patient.' }] } },
{ courseCode: 'FORM-CREATE', order: 18, title: 'Knowledge Check: Publishing', type: 'knowledge-check', content: 'Test publishing and versioning knowledge.', interactiveConfig: { sectionTitle: 'Publishing', questions: [{ id: 'fc-3', question: 'What is required to publish a form?', type: 'multiple-choice', options: ['Manager approval email', 'E-signature (username + password + reason)', 'Just clicking Publish', 'Waiting 24 hours'], correctIndex: 1, explanation: 'Publishing requires e-signature per 21 CFR Part 11 compliance.' }, { id: 'fc-4', question: 'After publishing v1.0 and making changes, what happens to existing data?', type: 'multiple-choice', options: ['It migrates to v2.0 automatically', 'It stays on v1.0 — both versions coexist', 'It gets deleted', 'It must be re-entered'], correctIndex: 1, explanation: 'Existing data stays on the original version. New patients get the new version.' }] } },
{ courseCode: 'FORM-CREATE', order: 19, title: 'Exercise: Complete Form Creation', type: 'interactive', content: 'Configure a complete form.', interactiveConfig: { type: 'fill-form', instruction: 'You need to create an Adverse Events form. Fill in the Info tab fields.', data: { fields: [{ label: 'Form Name', type: 'text', correctAnswer: 'any', placeholder: 'e.g., Adverse Events' }, { label: 'Category', type: 'select', correctAnswer: 'Safety', options: ['Safety', 'Efficacy', 'Administrative'] }, { label: 'Description', type: 'text', correctAnswer: 'any', placeholder: 'Describe the form purpose' }] }, successMessage: 'Correct! Adverse Events is a Safety form — this drives regulatory reporting workflows.', hintMessage: 'AE forms are always categorized as Safety forms.' } },
{ courseCode: 'FORM-CREATE', order: 20, title: 'Summary: eCRF Builder', type: 'text', content: '<h2>Key Takeaways</h2><ul><li>Forms have 4 tabs: Info → Design → Edit Checks → Preview</li><li>Use Quick Add for rapid field insertion</li><li>Choose correct field types (Text, Number, Date, Radio, Checkbox, Dropdown)</li><li>Set Variable Names as UPPERCASE with no spaces</li><li>Mark PHI fields appropriately</li><li>Use sections for logical grouping</li><li>Always Preview before Publishing</li><li>Publishing requires e-signature and creates a version</li></ul>' },
// ============ DATA-ENTRY (18 slides) ============
{ courseCode: 'DATA-ENTRY', order: 1, title: 'Navigating to a Patient Form', type: 'text', content: '<h2>Navigation Path</h2><p>To enter data: <strong>Patients → select patient → click Visit → click Form chip</strong></p><img src="assets/sop-screenshots/sop-029/01_navigation.png" alt="Navigation"><ul><li>Form chip colors: Gray=empty, Blue=in-progress, Green=complete, Gold=signed</li><li>Click any chip to open the form modal</li></ul>' },
{ courseCode: 'DATA-ENTRY', order: 2, title: 'The Visit Schedule', type: 'text', content: '<h2>Understanding the Visit Schedule</h2><p>Each patient has a timeline of scheduled visits. Each visit contains assigned forms.</p><table><tr><th>Visit Type</th><th>Description</th></tr><tr><td>Screening</td><td>Eligibility assessments</td></tr><tr><td>Baseline</td><td>Pre-treatment measurements</td></tr><tr><td>Treatment</td><td>On-study data collection</td></tr><tr><td>Follow-up</td><td>Post-treatment monitoring</td></tr><tr><td>Unscheduled</td><td>Ad-hoc visits (AEs, etc.)</td></tr></table>' },
{ courseCode: 'DATA-ENTRY', order: 3, title: 'Form Modal Layout', type: 'text', content: '<h2>Form Modal</h2><p>The form modal has three sections:</p><ul><li><strong>Header:</strong> Form name, version, status, patient ID, visit name</li><li><strong>Body:</strong> Fields organized in sections — scroll to complete</li><li><strong>Footer:</strong> Save Draft, Submit, Cancel buttons + validation summary</li></ul><p>Required fields show asterisk (*). Calculated fields are grayed out (auto-populated).</p>' },
{ courseCode: 'DATA-ENTRY', order: 4, title: 'Entering Data by Field Type', type: 'text', content: '<h2>Field Types in Practice</h2><table><tr><th>Type</th><th>How to Enter</th></tr><tr><td>Text</td><td>Type directly</td></tr><tr><td>Number</td><td>Type value; system validates range</td></tr><tr><td>Date</td><td>Use date picker or type DD-MMM-YYYY</td></tr><tr><td>Dropdown</td><td>Click to open, search or scroll, select</td></tr><tr><td>Radio</td><td>Click one option</td></tr><tr><td>Checkbox</td><td>Click all that apply</td></tr></table><p>Skip logic hides irrelevant fields automatically as you enter data.</p>' },
{ courseCode: 'DATA-ENTRY', order: 5, title: 'Exercise: Enter Vital Signs', type: 'interactive', content: 'Practice entering clinical data.', interactiveConfig: { type: 'fill-form', instruction: 'Enter vital signs for a Baseline visit. Use realistic clinical values.', data: { fields: [{ label: 'Systolic BP (mmHg)', type: 'number', correctAnswer: 'any', placeholder: '90-180' }, { label: 'Diastolic BP (mmHg)', type: 'number', correctAnswer: 'any', placeholder: '60-110' }, { label: 'Heart Rate (bpm)', type: 'number', correctAnswer: 'any', placeholder: '50-100' }, { label: 'Temperature (°C)', type: 'number', correctAnswer: 'any', placeholder: '36.0-38.0' }, { label: 'Weight (kg)', type: 'number', correctAnswer: 'any', placeholder: '40-150' }] }, successMessage: 'Data entered! In the real system, validation rules would check these ranges.', hintMessage: 'Enter realistic values within normal clinical ranges.' } },
{ courseCode: 'DATA-ENTRY', order: 6, title: 'Validation Errors and Warnings', type: 'text', content: '<h2>Validation Messages</h2><table><tr><th>Color</th><th>Type</th><th>Action</th></tr><tr><td style="color:red">Red</td><td>Hard check — blocks save</td><td>MUST fix before submitting</td></tr><tr><td style="color:orange">Yellow</td><td>Soft check — warning</td><td>Review recommended, can submit</td></tr></table><ul><li>Red blocks appear at the field and in the footer summary</li><li>Yellow warnings show a caution icon but allow submission</li><li>Query indicators (blue dot) mean a data query exists on that field</li></ul>' },
{ courseCode: 'DATA-ENTRY', order: 7, title: 'Exercise: Handle a Validation Error', type: 'interactive', content: 'Respond to validation messages correctly.', interactiveConfig: { type: 'scenario', instruction: 'You entered Heart Rate = 300 bpm. A RED error appears: "Value out of range (40-200)"', data: { context: 'The source document shows HR = 30 (the patient is bradycardic). You mistyped 300 instead of 30.', choices: [{ text: 'Correct the value to 30 and resubmit', correct: true, feedback: 'Correct! Fix the typo to match the source document.' }, { text: 'Submit anyway', correct: false, feedback: 'Red errors block submission — you cannot submit until resolved.' }, { text: 'Delete the value and leave blank', correct: false, feedback: 'HR is required. Correct it to the source document value.' }] }, successMessage: 'Always verify against the source document when fixing validation errors.' } },
{ courseCode: 'DATA-ENTRY', order: 8, title: 'Saving Drafts', type: 'text', content: '<h2>Save Draft vs Submit</h2><ul><li><strong>Save Draft:</strong> Saves entered data without completing. Form stays "In Progress" (blue). Return anytime to continue.</li><li><strong>Submit:</strong> Marks form as Complete (green). Requires all required fields filled. May trigger e-signature.</li></ul><p>Drafts auto-save every 60 seconds. You can close and return later without losing work.</p>' },
{ courseCode: 'DATA-ENTRY', order: 9, title: 'Submitting with E-Signature', type: 'text', content: '<h2>Submit & Sign</h2><p>When you click Submit on a form requiring signature:</p><ol><li>System validates all required fields</li><li>E-signature dialog appears</li><li>Enter: Username + Password + Reason for signing</li><li>Click Confirm → form becomes Signed (gold, locked)</li></ol><p>Per 21 CFR Part 11, the signature is legally binding and non-repudiable.</p>' },
{ courseCode: 'DATA-ENTRY', order: 10, title: 'Exercise: Submit and Sign a Form', type: 'interactive', content: 'Complete the submission workflow.', interactiveConfig: { type: 'order-steps', instruction: 'Put the form submission steps in correct order.', data: { steps: [{ id: 's1', text: 'Complete all required fields' }, { id: 's2', text: 'Review data for accuracy' }, { id: 's3', text: 'Click Submit button' }, { id: 's4', text: 'Enter username and password' }, { id: 's5', text: 'Enter reason for signing' }, { id: 's6', text: 'Click Confirm' }], correctOrder: ['s1', 's2', 's3', 's4', 's5', 's6'] }, successMessage: 'Correct! The form is now signed and locked.' } },
{ courseCode: 'DATA-ENTRY', order: 11, title: 'Making Corrections (Reason for Change)', type: 'text', content: '<h2>Correcting Submitted Data</h2><p>To edit a signed/submitted form:</p><ol><li>Request unlock (or unlock if you have permission)</li><li>Edit the field value</li><li>Enter a Reason for Change (mandatory)</li><li>Re-sign the form</li></ol><p>The audit trail permanently records: original value, new value, who changed it, when, and why.</p>' },
{ courseCode: 'DATA-ENTRY', order: 12, title: 'Exercise: Make a Correction', type: 'interactive', content: 'Practice correcting submitted data.', interactiveConfig: { type: 'fill-form', instruction: 'Weight was entered as 750 kg (should be 75.0 kg). Complete the correction.', data: { fields: [{ label: 'Corrected Value', type: 'text', correctAnswer: '75.0', placeholder: 'Enter correct weight' }, { label: 'Reason for Change', type: 'text', correctAnswer: 'any', placeholder: 'e.g., Transcription error per source document' }] }, successMessage: 'Correction recorded with audit trail entry.', hintMessage: 'Always reference the source document in your reason.' } },
{ courseCode: 'DATA-ENTRY', order: 13, title: 'Audit Trail', type: 'text', content: '<h2>Audit Trail</h2><p>Every action on a form is logged permanently:</p><ul><li>Data entry (who entered what, when)</li><li>Modifications (old value → new value + reason)</li><li>Signatures (who signed, timestamp, meaning)</li><li>Status changes (draft → complete → signed)</li></ul><p>Audit trails cannot be modified or deleted. They are the regulatory record of data integrity.</p>' },
{ courseCode: 'DATA-ENTRY', order: 14, title: 'Form States Summary', type: 'text', content: '<h2>Form State Lifecycle</h2><table><tr><th>State</th><th>Color</th><th>Meaning</th><th>Editable?</th></tr><tr><td>Empty</td><td>Gray</td><td>No data entered</td><td>Yes</td></tr><tr><td>In Progress</td><td>Blue</td><td>Draft saved</td><td>Yes</td></tr><tr><td>Complete</td><td>Green</td><td>Submitted</td><td>With reason</td></tr><tr><td>Signed</td><td>Gold</td><td>E-signed, locked</td><td>Unlock + reason</td></tr><tr><td>Frozen</td><td>Purple</td><td>SDV complete</td><td>No</td></tr><tr><td>Locked</td><td>Red</td><td>Database lock</td><td>No</td></tr></table>' },
{ courseCode: 'DATA-ENTRY', order: 15, title: 'Knowledge Check: Data Entry', type: 'knowledge-check', content: 'Test your data entry knowledge.', interactiveConfig: { sectionTitle: 'Data Entry Basics', questions: [{ id: 'de-1', question: 'What color is a form chip that has been e-signed?', type: 'multiple-choice', options: ['Green', 'Blue', 'Gold', 'Gray'], correctIndex: 2, explanation: 'Gold indicates a signed (locked) form.' }, { id: 'de-2', question: 'Red validation errors:', type: 'multiple-choice', options: ['Can be ignored', 'Block submission until fixed', 'Auto-resolve after 24h', 'Only appear for admins'], correctIndex: 1, explanation: 'Red (hard) checks block form submission.' }] } },
{ courseCode: 'DATA-ENTRY', order: 16, title: 'Knowledge Check: Corrections', type: 'knowledge-check', content: 'Test correction workflow knowledge.', interactiveConfig: { sectionTitle: 'Corrections & Audit', questions: [{ id: 'de-3', question: 'When correcting submitted data, what is required?', type: 'multiple-choice', options: ['Nothing — just edit', 'A reason for change', 'Manager email approval', 'Delete and re-enter entire form'], correctIndex: 1, explanation: 'Every correction requires a documented reason for change.' }, { id: 'de-4', question: 'True or False: Original values are permanently deleted after correction.', type: 'true-false', options: ['True', 'False'], correctIndex: 1, explanation: 'Original values are preserved forever in the audit trail.' }] } },
{ courseCode: 'DATA-ENTRY', order: 17, title: 'Exercise: Form State Identification', type: 'interactive', content: 'Match form states to their properties.', interactiveConfig: { type: 'match-pairs', instruction: 'Match each form state to its key characteristic.', data: { pairs: [{ left: 'Empty (Gray)', right: 'No data entered yet' }, { left: 'In Progress (Blue)', right: 'Draft saved, freely editable' }, { left: 'Signed (Gold)', right: 'Locked, requires unlock to edit' }, { left: 'Frozen (Purple)', right: 'SDV complete, cannot edit' }] }, successMessage: 'You understand the form lifecycle!' } },
{ courseCode: 'DATA-ENTRY', order: 18, title: 'Summary: Data Entry', type: 'text', content: '<h2>Key Takeaways</h2><ul><li>Navigate: Patients → Visit → Form chip</li><li>Chip colors indicate form state</li><li>Red errors block save; yellow warnings allow it</li><li>Save Draft to continue later; Submit to complete</li><li>E-signature locks the form (21 CFR Part 11)</li><li>Corrections require Reason for Change</li><li>Audit trail records everything permanently</li></ul>' },
// ============ PATIENT-MGMT (15 slides) ============
{ courseCode: 'PATIENT-MGMT', order: 1, title: 'Patients Page Overview', type: 'text', content: '<h2>Patients Page</h2><img src="assets/sop-screenshots/sop-026/01_patients_list.png" alt="Patients Page"><ul><li>Lists all enrolled subjects with status, site, and progress</li><li>Search by Subject ID, name initials, or site</li><li>Filter by: enrollment status, site, visit window</li><li>Click any row to open patient detail view</li></ul>' },
{ courseCode: 'PATIENT-MGMT', order: 2, title: 'Search and Filters', type: 'text', content: '<h2>Finding Patients</h2><ul><li><strong>Search bar:</strong> Type Subject ID or initials for instant results</li><li><strong>Status filter:</strong> Screening, Enrolled, Completed, Withdrawn</li><li><strong>Site filter:</strong> Filter by investigator site</li><li><strong>Visit window:</strong> Show patients with upcoming/overdue visits</li></ul><p>Combine filters to narrow results. Ctrl+K global search also finds patients.</p>' },
{ courseCode: 'PATIENT-MGMT', order: 3, title: 'Enrollment Wizard — 3 Steps', type: 'text', content: '<h2>Enrolling a New Patient</h2><p>Click "+ Enroll Patient" to start the 3-step wizard:</p><ol><li><strong>Step 1 — Demographics:</strong> Initials, DOB, sex, site assignment</li><li><strong>Step 2 — Eligibility:</strong> Confirm inclusion/exclusion criteria met</li><li><strong>Step 3 — Confirm:</strong> Review details, generate Subject ID, e-sign</li></ol><p>Subject ID is auto-generated based on site prefix + sequence number (e.g., SITE01-001).</p>' },
{ courseCode: 'PATIENT-MGMT', order: 4, title: 'Exercise: Enroll a New Patient', type: 'interactive', content: 'Complete the enrollment form.', interactiveConfig: { type: 'fill-form', instruction: 'Fill in the enrollment wizard Step 1 for a new patient at Site 01.', data: { fields: [{ label: 'Subject Initials', type: 'text', correctAnswer: 'any', placeholder: 'e.g., JDS' }, { label: 'Date of Birth', type: 'text', correctAnswer: 'any', placeholder: 'DD-MMM-YYYY' }, { label: 'Sex', type: 'select', correctAnswer: 'any', options: ['Male', 'Female', 'Other'] }, { label: 'Site', type: 'select', correctAnswer: 'Site 01', options: ['Site 01', 'Site 02', 'Site 03'] }] }, successMessage: 'Step 1 complete! In the real system you would proceed to eligibility confirmation.', hintMessage: 'All fields are required for enrollment.' } },
{ courseCode: 'PATIENT-MGMT', order: 5, title: 'Subject ID Generation', type: 'text', content: '<h2>Subject ID Rules</h2><ul><li>Format: [Site Prefix]-[Sequence] (e.g., SITE01-001)</li><li>Auto-generated — never manually entered</li><li>Unique across the entire study</li><li>Cannot be changed after enrollment</li><li>Used for all data, queries, and reports</li></ul><p>The ID links the patient to their study data while maintaining privacy (no real names in the system).</p>' },
{ courseCode: 'PATIENT-MGMT', order: 6, title: 'Patient Detail View', type: 'text', content: '<h2>Patient Detail View</h2><p>Click a patient to see their complete record:</p><ul><li><strong>Header:</strong> Subject ID, status, site, enrollment date</li><li><strong>Visit Timeline:</strong> Horizontal bar showing all scheduled visits</li><li><strong>Form Chips:</strong> Within each visit, colored chips for each form</li><li><strong>Activity Log:</strong> Recent data entry, queries, signatures</li></ul><img src="assets/sop-screenshots/sop-026/02_patient_detail.png" alt="Patient Detail">' },
{ courseCode: 'PATIENT-MGMT', order: 7, title: 'Visit Timeline and Form Chips', type: 'text', content: '<h2>Visit Timeline</h2><p>The timeline shows visits chronologically. Each visit expands to show form chips:</p><table><tr><th>Chip Color</th><th>Meaning</th></tr><tr><td>Gray</td><td>Empty — no data entered</td></tr><tr><td>Blue</td><td>In Progress — partially filled</td></tr><tr><td>Green</td><td>Complete — all required fields done</td></tr><tr><td>Gold</td><td>Signed — e-signed and locked</td></tr><tr><td>Red outline</td><td>Overdue — past visit window</td></tr></table>' },
{ courseCode: 'PATIENT-MGMT', order: 8, title: 'Exercise: Navigate Patient Record', type: 'interactive', content: 'Identify elements in the patient detail view.', interactiveConfig: { type: 'match-pairs', instruction: 'Match each element to where it appears in the patient detail view.', data: { pairs: [{ left: 'Subject ID & enrollment date', right: 'Header section' }, { left: 'Scheduled visits in order', right: 'Visit Timeline' }, { left: 'Colored squares for each CRF', right: 'Form Chips' }, { left: 'Recent actions and changes', right: 'Activity Log' }] }, successMessage: 'You can navigate the patient detail view confidently!' } },
{ courseCode: 'PATIENT-MGMT', order: 9, title: 'Scheduling Visits', type: 'text', content: '<h2>Visit Scheduling</h2><ul><li>Visits are pre-defined in the study protocol</li><li>Visit windows: target date ± allowed deviation</li><li>System highlights overdue visits (red outline)</li><li><strong>Unscheduled visits:</strong> Click "+ Add Unscheduled Visit" for ad-hoc assessments (AEs, early termination)</li></ul><p>Visit dates are tracked for protocol compliance metrics.</p>' },
{ courseCode: 'PATIENT-MGMT', order: 10, title: 'Unscheduled Visits', type: 'text', content: '<h2>Unscheduled Visits</h2><p>For events outside the normal schedule:</p><ol><li>Click "+ Add Unscheduled Visit" on patient timeline</li><li>Select visit type (AE Follow-up, Protocol Deviation, etc.)</li><li>Set the visit date</li><li>Assign relevant forms</li></ol><p>Unscheduled visits appear on the timeline with a dashed border to distinguish them from protocol-defined visits.</p>' },
{ courseCode: 'PATIENT-MGMT', order: 11, title: 'Transferring Patients', type: 'text', content: '<h2>Patient Transfer</h2><p>To transfer a patient to a different site:</p><ol><li>Open patient detail → Actions → Transfer</li><li>Select destination site</li><li>Enter reason for transfer</li><li>E-sign the transfer</li></ol><p>Transfer preserves all data. The Subject ID remains the same. Audit trail records the site change.</p>' },
{ courseCode: 'PATIENT-MGMT', order: 12, title: 'Knowledge Check: Enrollment', type: 'knowledge-check', content: 'Test enrollment knowledge.', interactiveConfig: { sectionTitle: 'Enrollment', questions: [{ id: 'pm-1', question: 'How many steps in the enrollment wizard?', type: 'multiple-choice', options: ['1', '2', '3', '5'], correctIndex: 2, explanation: 'The wizard has 3 steps: Demographics, Eligibility, Confirm.' }, { id: 'pm-2', question: 'Subject IDs are:', type: 'multiple-choice', options: ['Manually entered by the user', 'Auto-generated by the system', 'The patient real name', 'Random letters'], correctIndex: 1, explanation: 'Subject IDs are auto-generated (site prefix + sequence) for consistency.' }] } },
{ courseCode: 'PATIENT-MGMT', order: 13, title: 'Knowledge Check: Navigation', type: 'knowledge-check', content: 'Test patient navigation knowledge.', interactiveConfig: { sectionTitle: 'Patient Navigation', questions: [{ id: 'pm-3', question: 'A red-outlined visit on the timeline means:', type: 'multiple-choice', options: ['Visit is complete', 'Visit is overdue', 'Visit was cancelled', 'Visit has errors'], correctIndex: 1, explanation: 'Red outline indicates the visit is past its allowed window (overdue).' }, { id: 'pm-4', question: 'True or False: Unscheduled visits appear with a dashed border.', type: 'true-false', options: ['True', 'False'], correctIndex: 0, explanation: 'Dashed borders distinguish unscheduled visits from protocol-defined ones.' }] } },
{ courseCode: 'PATIENT-MGMT', order: 14, title: 'Exercise: Enrollment Order', type: 'interactive', content: 'Put enrollment steps in order.', interactiveConfig: { type: 'order-steps', instruction: 'Arrange the full enrollment workflow.', data: { steps: [{ id: 's1', text: 'Click "+ Enroll Patient"' }, { id: 's2', text: 'Enter demographics (initials, DOB, sex, site)' }, { id: 's3', text: 'Confirm eligibility criteria' }, { id: 's4', text: 'Review and confirm details' }, { id: 's5', text: 'E-sign to complete enrollment' }], correctOrder: ['s1', 's2', 's3', 's4', 's5'] }, successMessage: 'Correct enrollment workflow!' } },
{ courseCode: 'PATIENT-MGMT', order: 15, title: 'Summary: Patient Management', type: 'text', content: '<h2>Key Takeaways</h2><ul><li>Search/filter patients by ID, site, status</li><li>Enrollment wizard: Demographics → Eligibility → Confirm + E-sign</li><li>Subject IDs auto-generated, never editable</li><li>Patient detail shows timeline + form chips</li><li>Chip colors = form states (gray/blue/green/gold)</li><li>Add unscheduled visits for ad-hoc events</li><li>Transfers preserve data and require e-signature</li></ul>' },
// ============ QUERY-MGMT (15 slides) ============
{ courseCode: 'QUERY-MGMT', order: 1, title: 'What Are Queries?', type: 'text', content: '<h2>Data Queries</h2><p>Queries are formal questions about data entered in CRFs. They drive data cleaning and ensure accuracy.</p><table><tr><th>Query Type</th><th>Source</th></tr><tr><td>Manual</td><td>Created by monitors/DMs on a specific field</td></tr><tr><td>Auto (Validation)</td><td>Generated by validation rules automatically</td></tr><tr><td>Annotation</td><td>Notes/comments on data points</td></tr></table><img src="assets/sop-screenshots/sop-020/01_queries_dashboard.png" alt="Queries Dashboard">' },
{ courseCode: 'QUERY-MGMT', order: 2, title: 'Query Severity Levels', type: 'text', content: '<h2>Severity Levels</h2><table><tr><th>Level</th><th>Meaning</th><th>Impact</th></tr><tr><td>Critical</td><td>Patient safety or primary endpoint issue</td><td>Must resolve before database lock</td></tr><tr><td>Major</td><td>Significant data discrepancy</td><td>Must resolve before analysis</td></tr><tr><td>Minor</td><td>Non-critical clarification needed</td><td>Should resolve, can proceed</td></tr></table><p>Severity determines urgency and workflow routing.</p>' },
{ courseCode: 'QUERY-MGMT', order: 3, title: 'Queries Dashboard', type: 'text', content: '<h2>Queries Dashboard</h2><p>Navigate: Sidebar → Queries. The dashboard shows:</p><ul><li><strong>Summary cards:</strong> Open, Answered, Closed counts</li><li><strong>Filters:</strong> Status, severity, site, form, assignee</li><li><strong>Bulk actions:</strong> Select multiple → Close, Reassign, Export</li><li><strong>Table:</strong> Query ID, field, patient, status, age (days open)</li></ul>' },
{ courseCode: 'QUERY-MGMT', order: 4, title: 'Creating a Manual Query', type: 'text', content: '<h2>Creating a Query</h2><p>To create a query on a specific field:</p><ol><li>Open the form containing the questionable data</li><li>Click the query icon (flag) next to the field</li><li>Enter: Query text, severity, assignee</li><li>Click Create → query appears as blue dot on the field</li></ol><p>Be specific: "Please verify systolic BP of 45 — appears below expected range per protocol."</p>' },
{ courseCode: 'QUERY-MGMT', order: 5, title: 'Exercise: Create a Query', type: 'interactive', content: 'Practice creating a data query.', interactiveConfig: { type: 'fill-form', instruction: 'Create a query for a weight value of 8.5 kg on an adult patient.', data: { fields: [{ label: 'Query Text', type: 'text', correctAnswer: 'any', placeholder: 'Describe the issue clearly' }, { label: 'Severity', type: 'select', correctAnswer: 'Major', options: ['Critical', 'Major', 'Minor'] }, { label: 'Assigned To', type: 'select', correctAnswer: 'any', options: ['Site Coordinator', 'Investigator', 'Data Manager'] }] }, successMessage: 'Query created! The site will receive a notification to respond.', hintMessage: 'An adult weighing 8.5 kg is a significant data error — likely should be 85 kg.' } },
{ courseCode: 'QUERY-MGMT', order: 6, title: 'Responding to a Query', type: 'text', content: '<h2>Responding to Queries</h2><p>When you receive a query:</p><ol><li>Open the query (from dashboard or field indicator)</li><li>Review the question and check source documents</li><li>Enter response text explaining the value</li><li>Optionally propose a corrected value</li><li>Click Submit Response → status changes to "Answered"</li></ol><p>Always reference source documents in your response.</p>' },
{ courseCode: 'QUERY-MGMT', order: 7, title: 'Exercise: Respond to a Query', type: 'interactive', content: 'Practice responding to a query.', interactiveConfig: { type: 'fill-form', instruction: 'Query asks: "Please verify Heart Rate of 180 bpm — exceeds normal range." Source doc shows HR was actually 80.', data: { fields: [{ label: 'Response Text', type: 'text', correctAnswer: 'any', placeholder: 'Explain and reference source' }, { label: 'Proposed Corrected Value', type: 'text', correctAnswer: '80', placeholder: 'Enter corrected value if applicable' }] }, successMessage: 'Response submitted! The monitor will review and accept/reject.', hintMessage: 'Reference the source document and propose the correct value.' } },
{ courseCode: 'QUERY-MGMT', order: 8, title: 'Query Lifecycle', type: 'text', content: '<h2>Query States</h2><p>Open → Answered → Accepted/Rejected → Closed</p><ul><li><strong>Open:</strong> Awaiting site response</li><li><strong>Answered:</strong> Site responded, awaiting review</li><li><strong>Accepted:</strong> Response satisfactory, correction applied</li><li><strong>Rejected:</strong> Response insufficient, re-opened for more info</li><li><strong>Closed:</strong> Resolved with e-signature</li></ul><p>Closing requires e-signature (21 CFR Part 11).</p>' },
{ courseCode: 'QUERY-MGMT', order: 9, title: 'Exercise: Query Lifecycle Order', type: 'interactive', content: 'Order the query lifecycle steps.', interactiveConfig: { type: 'order-steps', instruction: 'Put the query lifecycle in correct order.', data: { steps: [{ id: 's1', text: 'Monitor creates query (Open)' }, { id: 's2', text: 'Site responds with explanation (Answered)' }, { id: 's3', text: 'Monitor reviews response' }, { id: 's4', text: 'Monitor accepts and correction is applied' }, { id: 's5', text: 'Query closed with e-signature' }], correctOrder: ['s1', 's2', 's3', 's4', 's5'] }, successMessage: 'Correct query lifecycle!' } },
{ courseCode: 'QUERY-MGMT', order: 10, title: 'Auto-Queries from Validation Rules', type: 'text', content: '<h2>Automatic Queries</h2><p>Validation rules can auto-generate queries when soft checks fail:</p><ul><li>Configured in Validation Rules page (rule severity = "Create Query")</li><li>Auto-queries include the rule message as query text</li><li>Assigned to the data entry user automatically</li><li>Same lifecycle as manual queries</li></ul><p>This automates data cleaning — no manual monitor review needed for routine checks.</p>' },
{ courseCode: 'QUERY-MGMT', order: 11, title: 'Workflow Routing', type: 'text', content: '<h2>Query Routing</h2><ul><li>Queries route to assignees based on role and site</li><li>Notifications sent via in-app alerts and email</li><li>Overdue queries (>7 days) escalate to site PI</li><li>Dashboard shows "My Queries" for personal queue</li></ul><p>Bulk operations: Select multiple queries → Reassign, Close, or Export to CSV.</p>' },
{ courseCode: 'QUERY-MGMT', order: 12, title: 'Closing Queries', type: 'text', content: '<h2>Closing with E-Signature</h2><p>Only authorized users (monitors, DMs) can close queries:</p><ol><li>Review the response and any corrected values</li><li>Click "Close Query"</li><li>E-signature dialog: username + password + reason</li><li>Query moves to Closed state permanently</li></ol><p>Closed queries cannot be reopened. If further issues found, create a new query.</p>' },
{ courseCode: 'QUERY-MGMT', order: 13, title: 'Knowledge Check: Query Basics', type: 'knowledge-check', content: 'Test query management knowledge.', interactiveConfig: { sectionTitle: 'Query Basics', questions: [{ id: 'qm-1', question: 'Who can close a query?', type: 'multiple-choice', options: ['Any user', 'Only the site coordinator', 'Authorized monitors/DMs with e-signature', 'System auto-closes after 30 days'], correctIndex: 2, explanation: 'Closing requires authorization and e-signature.' }, { id: 'qm-2', question: 'Auto-queries are generated by:', type: 'multiple-choice', options: ['Random system checks', 'Validation rules with "Create Query" severity', 'Patient complaints', 'Monthly audits'], correctIndex: 1, explanation: 'Validation rules configured with query severity auto-create queries on failure.' }] } },
{ courseCode: 'QUERY-MGMT', order: 14, title: 'Knowledge Check: Lifecycle', type: 'knowledge-check', content: 'Test lifecycle knowledge.', interactiveConfig: { sectionTitle: 'Query Lifecycle', questions: [{ id: 'qm-3', question: 'After a site responds, the query status becomes:', type: 'multiple-choice', options: ['Closed', 'Answered', 'Rejected', 'Deleted'], correctIndex: 1, explanation: 'Answered means the site responded and the monitor needs to review.' }, { id: 'qm-4', question: 'True or False: Closed queries can be reopened.', type: 'true-false', options: ['True', 'False'], correctIndex: 1, explanation: 'Closed queries are permanent. Create a new query if needed.' }] } },
{ courseCode: 'QUERY-MGMT', order: 15, title: 'Summary: Query Management', type: 'text', content: '<h2>Key Takeaways</h2><ul><li>Queries = formal questions about CRF data</li><li>Types: Manual, Auto (validation), Annotation</li><li>Lifecycle: Open → Answered → Accepted → Closed</li><li>Creating: Click field flag → enter text + severity</li><li>Responding: Check source docs → explain → propose correction</li><li>Closing requires e-signature</li><li>Auto-queries reduce manual monitoring workload</li></ul>' },
// ============ VAL-RULES (18 slides) ============
{ courseCode: 'VAL-RULES', order: 1, title: 'Why Validation Rules Matter', type: 'text', content: '<h2>Purpose of Validation Rules</h2><p>Validation rules catch data errors at the point of entry, reducing queries and improving data quality.</p><ul><li>Prevent impossible values (e.g., age > 150)</li><li>Enforce cross-field consistency (systolic > diastolic)</li><li>Auto-generate queries for soft violations</li><li>Reduce downstream data cleaning by 60-80%</li></ul><img src="assets/sop-screenshots/sop-019/01_validation_rules.png" alt="Validation Rules">' },
{ courseCode: 'VAL-RULES', order: 2, title: 'Navigating to Validation Rules', type: 'text', content: '<h2>Navigation</h2><p>Sidebar → Forms → select a form → Validation Rules tab</p><ul><li>Rules are form-specific and field-specific</li><li>Per-field card view shows all rules on each field</li><li>Color coding: Green=active, Gray=disabled, Red=error in rule</li><li>Badge count shows total rules per field</li></ul><img src="assets/sop-screenshots/sop-019/02_per_field_view.png" alt="Per-Field View">' },
{ courseCode: 'VAL-RULES', order: 3, title: 'Quick Add — 28 Templates', type: 'text', content: '<h2>Quick Add Templates</h2><p>Click "Quick Add" on any field to see categorized templates:</p><table><tr><th>Category</th><th>Examples</th></tr><tr><td>Range</td><td>Min/Max, Between, Outside range</td></tr><tr><td>Required</td><td>Required-if, Conditional required</td></tr><tr><td>Format</td><td>Date format, Phone, Email, Pattern</td></tr><tr><td>Cross-field</td><td>Greater than field, Less than field, Equal to</td></tr><tr><td>Date</td><td>Before today, After consent, Within window</td></tr><tr><td>Custom</td><td>Regex match, Formula, Script</td></tr></table><p>Templates auto-configure — just confirm and save.</p>' },
{ courseCode: 'VAL-RULES', order: 4, title: 'AI Rule Suggester', type: 'text', content: '<h2>AI-Powered Suggestions</h2><p>Click "AI Suggest" to get intelligent rule recommendations based on:</p><ul><li>Field type and name (e.g., "age" → range 0-120)</li><li>CDASH standards for the domain</li><li>Common clinical validation patterns</li><li>Your study protocol requirements</li></ul><p>Review each suggestion before accepting. AI provides the starting point — you verify clinical appropriateness.</p>' },
{ courseCode: 'VAL-RULES', order: 5, title: 'Custom Rule Builder — Overview', type: 'text', content: '<h2>Custom Rule Builder (6 Steps)</h2><p>For rules not covered by templates, use the wizard:</p><ol><li><strong>Select Field:</strong> Which field to validate</li><li><strong>Check Type:</strong> Range, pattern, cross-field, formula, custom</li><li><strong>Configure:</strong> Set values, operators, thresholds</li><li><strong>Severity:</strong> Block Save vs. Create Query</li><li><strong>Name & Message:</strong> Rule ID and user-facing error text</li><li><strong>Create:</strong> Review and confirm with e-signature</li></ol>' },
{ courseCode: 'VAL-RULES', order: 6, title: 'Custom Rule Builder — Configuration', type: 'text', content: '<h2>Step 3: Configure the Rule</h2><p>Configuration depends on check type:</p><table><tr><th>Check Type</th><th>Config Options</th></tr><tr><td>Range</td><td>Min value, Max value, Inclusive/Exclusive</td></tr><tr><td>Pattern</td><td>Regex expression, case sensitivity</td></tr><tr><td>Cross-field</td><td>Comparison field, operator (>, <, =, ≠)</td></tr><tr><td>Formula</td><td>JavaScript expression returning boolean</td></tr><tr><td>Date logic</td><td>Reference date, offset days, direction</td></tr></table>' },
{ courseCode: 'VAL-RULES', order: 7, title: 'Severity: Block Save vs Create Query', type: 'text', content: '<h2>Choosing Severity</h2><table><tr><th>Severity</th><th>Behavior</th><th>Use When</th></tr><tr><td>Block Save (Hard)</td><td>Prevents form submission — RED error</td><td>Impossible values, safety limits, format violations</td></tr><tr><td>Create Query (Soft)</td><td>Allows submission but creates a query — YELLOW warning</td><td>Unusual but possible values, protocol deviations, clinical review needed</td></tr></table><p><strong>Rule of thumb:</strong> If a clinician might validly enter the value, use "Create Query." If it is physically impossible, use "Block Save."</p>' },
{ courseCode: 'VAL-RULES', order: 8, title: 'Exercise: Create a Range Check', type: 'interactive', content: 'Configure a validation rule.', interactiveConfig: { type: 'fill-form', instruction: 'Create a range check for Diastolic BP (normal range 40-130, critical concern outside 30-180).', data: { fields: [{ label: 'Field', type: 'text', correctAnswer: 'Diastolic BP', placeholder: 'Which field?' }, { label: 'Min Value (Hard check)', type: 'number', correctAnswer: '30', placeholder: 'Absolute minimum' }, { label: 'Max Value (Hard check)', type: 'number', correctAnswer: '180', placeholder: 'Absolute maximum' }, { label: 'Severity for 40-130 range', type: 'select', correctAnswer: 'Create Query', options: ['Block Save', 'Create Query'] }, { label: 'Severity for 30-180 range', type: 'select', correctAnswer: 'Block Save', options: ['Block Save', 'Create Query'] }] }, successMessage: 'Correct! Hard limits (30-180) block save. Soft limits (40-130) create queries for review.', hintMessage: 'Values outside 30-180 are physically impossible. Values outside 40-130 are unusual but possible.' } },
{ courseCode: 'VAL-RULES', order: 9, title: 'Exercise: Choose the Right Severity', type: 'interactive', content: 'Decide severity for each scenario.', interactiveConfig: { type: 'match-pairs', instruction: 'Match each validation scenario to the correct severity.', data: { pairs: [{ left: 'Age entered as 250 years', right: 'Block Save' }, { left: 'Weight is 45 kg (low but possible)', right: 'Create Query' }, { left: 'Date format is "13/25/2024" (invalid)', right: 'Block Save' }, { left: 'Heart rate is 110 bpm (elevated)', right: 'Create Query' }, { left: 'End date is before start date', right: 'Block Save' }] }, successMessage: 'You understand when to block vs. query!' } },
{ courseCode: 'VAL-RULES', order: 10, title: 'Testing Rules', type: 'text', content: '<h2>Testing Your Rules</h2><p>After creating a rule, test it before publishing:</p><ol><li>Click "Test Rule" on the rule card</li><li>Enter sample values (passing and failing)</li><li>Verify: correct values pass, incorrect values trigger the expected behavior</li><li>Check the error message displays clearly</li></ol><p>Test edge cases: boundary values, null/empty, maximum length strings.</p>' },
{ courseCode: 'VAL-RULES', order: 11, title: 'Managing Rules', type: 'text', content: '<h2>Rule Management</h2><ul><li><strong>Enable/Disable:</strong> Toggle without deleting — useful during study amendments</li><li><strong>Edit:</strong> Modify rule parameters (requires e-signature)</li><li><strong>Delete:</strong> Permanently remove (requires e-signature, logged in audit trail)</li><li><strong>Reorder:</strong> Rules execute in order — first failure shown to user</li><li><strong>Copy:</strong> Duplicate a rule to another field/form</li></ul>' },
{ courseCode: 'VAL-RULES', order: 12, title: 'Regex Reference', type: 'text', content: '<h2>Common Regex Patterns</h2><table><tr><th>Pattern</th><th>Use</th><th>Example</th></tr><tr><td>^[A-Z]{2,3}$</td><td>Initials (2-3 uppercase)</td><td>JD, MRS</td></tr><tr><td>^\\d{2}-[A-Z]{3}-\\d{4}$</td><td>Date (DD-MMM-YYYY)</td><td>15-JAN-2024</td></tr><tr><td>^\\d+(\\.\\d{1,2})?$</td><td>Number with up to 2 decimals</td><td>75.5, 120</td></tr><tr><td>^[A-Z0-9-]+$</td><td>Subject ID format</td><td>SITE01-001</td></tr></table><p>Use the regex tester in the Custom Rule Builder to validate patterns.</p>' },
{ courseCode: 'VAL-RULES', order: 13, title: 'E-Signature for Rule Changes', type: 'text', content: '<h2>Regulatory Requirement</h2><p>All validation rule changes require e-signature because rules directly affect data quality and patient safety:</p><ul><li>Creating a new rule → e-signature</li><li>Modifying an existing rule → e-signature</li><li>Deleting a rule → e-signature</li><li>Enabling/Disabling → e-signature</li></ul><p>The audit trail records who made each change, when, and the before/after state of the rule.</p>' },
{ courseCode: 'VAL-RULES', order: 14, title: 'Knowledge Check: Rule Basics', type: 'knowledge-check', content: 'Test validation rules knowledge.', interactiveConfig: { sectionTitle: 'Rule Basics', questions: [{ id: 'vr-1', question: 'What does "Block Save" severity do?', type: 'multiple-choice', options: ['Shows a yellow warning', 'Prevents form submission with a red error', 'Creates a query automatically', 'Sends an email to the monitor'], correctIndex: 1, explanation: 'Block Save = hard check = red error = cannot submit until fixed.' }, { id: 'vr-2', question: 'How many Quick Add templates are available?', type: 'multiple-choice', options: ['5', '12', '28', '50'], correctIndex: 2, explanation: 'There are 28 pre-built templates across 6 categories.' }] } },
{ courseCode: 'VAL-RULES', order: 15, title: 'Knowledge Check: Configuration', type: 'knowledge-check', content: 'Test rule configuration knowledge.', interactiveConfig: { sectionTitle: 'Rule Configuration', questions: [{ id: 'vr-3', question: 'The Custom Rule Builder has how many steps?', type: 'multiple-choice', options: ['3', '4', '6', '8'], correctIndex: 2, explanation: '6 steps: Field → Check Type → Configure → Severity → Name/Message → Create.' }, { id: 'vr-4', question: 'True or False: Deleting a validation rule requires e-signature.', type: 'true-false', options: ['True', 'False'], correctIndex: 0, explanation: 'All rule changes (create, edit, delete, enable/disable) require e-signature.' }] } },
{ courseCode: 'VAL-RULES', order: 16, title: 'Exercise: Rule Builder Steps', type: 'interactive', content: 'Order the Custom Rule Builder steps.', interactiveConfig: { type: 'order-steps', instruction: 'Put the 6 Custom Rule Builder steps in order.', data: { steps: [{ id: 's1', text: 'Select the target field' }, { id: 's2', text: 'Choose check type (range, pattern, cross-field, etc.)' }, { id: 's3', text: 'Configure values and thresholds' }, { id: 's4', text: 'Set severity (Block Save or Create Query)' }, { id: 's5', text: 'Enter rule name and error message' }, { id: 's6', text: 'Review and create with e-signature' }], correctOrder: ['s1', 's2', 's3', 's4', 's5', 's6'] }, successMessage: 'Correct! You know the Custom Rule Builder workflow.' } },
{ courseCode: 'VAL-RULES', order: 17, title: 'Exercise: Rule Scenarios', type: 'interactive', content: 'Choose the right rule type for each scenario.', interactiveConfig: { type: 'match-pairs', instruction: 'Match each validation need to the correct check type.', data: { pairs: [{ left: 'Weight must be between 20-300 kg', right: 'Range check' }, { left: 'End date must be after start date', right: 'Cross-field check' }, { left: 'Subject ID must match SITE##-### format', right: 'Pattern (regex) check' }, { left: 'BMI auto-calculated from height and weight', right: 'Formula check' }] }, successMessage: 'You can identify the right check type for each need!' } },
{ courseCode: 'VAL-RULES', order: 18, title: 'Summary: Validation Rules', type: 'text', content: '<h2>Key Takeaways</h2><ul><li>Rules catch errors at entry — fewer downstream queries</li><li>Quick Add: 28 templates for common checks</li><li>AI Suggester: intelligent recommendations based on field context</li><li>Custom Builder: 6-step wizard for complex rules</li><li>Block Save = physically impossible values (hard)</li><li>Create Query = unusual but possible values (soft)</li><li>All changes require e-signature (regulatory)</li><li>Test rules before publishing</li></ul>' },
// ============ STUDY-MGMT (12 slides) ============
{ courseCode: 'STUDY-MGMT', order: 1, title: 'Studies Page', type: 'text', content: '<h2>Studies Overview</h2><img src="assets/sop-screenshots/sop-025/01_studies_page.png" alt="Studies Page"><ul><li>Lists all studies with status, phase, enrollment count</li><li>Click a study to view/edit configuration</li><li>Only Study Managers and Admins can create studies</li><li>Active studies show real-time enrollment metrics</li></ul>' },
{ courseCode: 'STUDY-MGMT', order: 2, title: 'Study Creation — 8-Tab Wizard', type: 'text', content: '<h2>8-Tab Study Wizard</h2><ol><li><strong>Basic Info:</strong> Name, protocol number, phase, sponsor, therapeutic area</li><li><strong>Sites:</strong> Add participating sites with PI assignments</li><li><strong>Protocol:</strong> Upload protocol document, define objectives</li><li><strong>Visits/Events:</strong> Define visit schedule with windows</li><li><strong>Forms:</strong> Assign forms to visits</li><li><strong>Enrollment:</strong> Target numbers per site, stratification</li><li><strong>Randomization:</strong> Configure if applicable</li><li><strong>Review:</strong> Summary and publish with e-signature</li></ol>' },
{ courseCode: 'STUDY-MGMT', order: 3, title: 'Basic Info Tab', type: 'text', content: '<h2>Tab 1: Basic Info</h2><table><tr><th>Field</th><th>Example</th></tr><tr><td>Study Name</td><td>CARDIO-2024: Phase III Hypertension Trial</td></tr><tr><td>Protocol Number</td><td>PROTO-2024-001</td></tr><tr><td>Phase</td><td>Phase III</td></tr><tr><td>Sponsor</td><td>PharmaCorp Inc.</td></tr><tr><td>Therapeutic Area</td><td>Cardiology</td></tr><tr><td>Target Enrollment</td><td>500 subjects</td></tr></table>' },
{ courseCode: 'STUDY-MGMT', order: 4, title: 'Sites Configuration', type: 'text', content: '<h2>Tab 2: Sites</h2><ul><li>Add sites from your organization site list</li><li>Assign Principal Investigator per site</li><li>Set site-specific enrollment target</li><li>Configure site prefix for Subject IDs (e.g., S01, S02)</li><li>Sites can be activated/deactivated without deletion</li></ul><p>Sites must be fully configured before enrollment can begin at that location.</p>' },
{ courseCode: 'STUDY-MGMT', order: 5, title: 'Visits and Events', type: 'text', content: '<h2>Tab 4: Visit Schedule</h2><p>Define the study visit schedule:</p><table><tr><th>Property</th><th>Description</th></tr><tr><td>Visit Name</td><td>Display name (e.g., "Screening", "Week 4")</td></tr><tr><td>Visit Order</td><td>Sequence in timeline</td></tr><tr><td>Target Day</td><td>Day relative to enrollment (Day 0, Day 28, etc.)</td></tr><tr><td>Window (±)</td><td>Allowed deviation in days (e.g., ±3)</td></tr><tr><td>Required</td><td>Whether visit is mandatory</td></tr></table>' },
{ courseCode: 'STUDY-MGMT', order: 6, title: 'Assigning Forms to Visits', type: 'text', content: '<h2>Tab 5: Form Assignment</h2><p>Map which CRFs appear at each visit:</p><ul><li>Drag forms from the form library into visit columns</li><li>Set form as Required or Optional per visit</li><li>Same form can appear at multiple visits (e.g., Vitals at every visit)</li><li>Visit-specific forms (e.g., Screening only at Visit 1)</li></ul><p>This matrix determines what form chips appear for each patient at each visit.</p>' },
{ courseCode: 'STUDY-MGMT', order: 7, title: 'Enrollment Configuration', type: 'text', content: '<h2>Tab 6: Enrollment</h2><ul><li>Set total enrollment target and per-site targets</li><li>Configure enrollment cap (hard stop or warning)</li><li>Define stratification factors (age group, sex, site)</li><li>Set screening failure criteria</li><li>Configure enrollment period (start/end dates)</li></ul>' },
{ courseCode: 'STUDY-MGMT', order: 8, title: 'Exercise: Create a Study', type: 'interactive', content: 'Fill in basic study info.', interactiveConfig: { type: 'fill-form', instruction: 'Configure the Basic Info tab for a new oncology study.', data: { fields: [{ label: 'Study Name', type: 'text', correctAnswer: 'any', placeholder: 'e.g., ONCO-2024: Phase II Melanoma Trial' }, { label: 'Phase', type: 'select', correctAnswer: 'any', options: ['Phase I', 'Phase II', 'Phase III', 'Phase IV'] }, { label: 'Therapeutic Area', type: 'select', correctAnswer: 'Oncology', options: ['Cardiology', 'Oncology', 'Neurology', 'Infectious Disease'] }, { label: 'Target Enrollment', type: 'number', correctAnswer: 'any', placeholder: 'e.g., 200' }] }, successMessage: 'Basic info configured! Next you would set up sites and visits.' } },
{ courseCode: 'STUDY-MGMT', order: 9, title: 'Exercise: Define Visit Schedule', type: 'interactive', content: 'Order visits correctly.', interactiveConfig: { type: 'order-steps', instruction: 'Put these visits in the correct chronological order for a typical study.', data: { steps: [{ id: 's1', text: 'Screening (Day -14 to Day -1)' }, { id: 's2', text: 'Baseline / Randomization (Day 0)' }, { id: 's3', text: 'Week 2 Treatment Visit (Day 14 ±3)' }, { id: 's4', text: 'Week 4 Treatment Visit (Day 28 ±3)' }, { id: 's5', text: 'End of Treatment (Day 56 ±7)' }, { id: 's6', text: 'Follow-up (Day 84 ±7)' }], correctOrder: ['s1', 's2', 's3', 's4', 's5', 's6'] }, successMessage: 'Correct visit schedule order!' } },
{ courseCode: 'STUDY-MGMT', order: 10, title: 'Knowledge Check: Study Setup', type: 'knowledge-check', content: 'Test study management knowledge.', interactiveConfig: { sectionTitle: 'Study Setup', questions: [{ id: 'sm-1', question: 'How many tabs in the study creation wizard?', type: 'multiple-choice', options: ['4', '6', '8', '10'], correctIndex: 2, explanation: 'The wizard has 8 tabs: Basic Info, Sites, Protocol, Visits, Forms, Enrollment, Randomization, Review.' }, { id: 'sm-2', question: 'A visit window of ±3 means:', type: 'multiple-choice', options: ['Visit must happen exactly on target day', 'Visit can happen 3 days before or after target', 'Visit takes 3 days', 'Patient has 3 attempts'], correctIndex: 1, explanation: 'Window ±3 allows the visit within 3 days before or after the target day.' }] } },
{ courseCode: 'STUDY-MGMT', order: 11, title: 'Knowledge Check: Configuration', type: 'knowledge-check', content: 'Test configuration knowledge.', interactiveConfig: { sectionTitle: 'Study Configuration', questions: [{ id: 'sm-3', question: 'Who can create a new study?', type: 'multiple-choice', options: ['Any user', 'Only Study Managers and Admins', 'Only the sponsor', 'Only site PIs'], correctIndex: 1, explanation: 'Study creation is restricted to Study Manager and Admin roles.' }, { id: 'sm-4', question: 'True or False: The same form can be assigned to multiple visits.', type: 'true-false', options: ['True', 'False'], correctIndex: 0, explanation: 'Forms like Vital Signs commonly appear at every visit in the schedule.' }] } },
{ courseCode: 'STUDY-MGMT', order: 12, title: 'Summary: Study Management', type: 'text', content: '<h2>Key Takeaways</h2><ul><li>8-tab wizard: Info → Sites → Protocol → Visits → Forms → Enrollment → Randomization → Review</li><li>Visit windows define allowed scheduling deviation</li><li>Forms are assigned per-visit (same form can repeat)</li><li>Sites need PI assignment and Subject ID prefix</li><li>Publishing requires e-signature</li><li>Only Study Managers/Admins can create studies</li></ul>' },
// ============ BRANCHING (10 slides) ============
{ courseCode: 'BRANCHING', order: 1, title: 'What is Branching Logic?', type: 'text', content: '<h2>Branching Logic (Skip Logic)</h2><p>Branching controls field/section visibility based on other field values. It simplifies forms by hiding irrelevant questions.</p><ul><li>Show field B only when field A = "Yes"</li><li>Hide entire sections based on conditions</li><li>Reduces data entry burden</li><li>Prevents collection of irrelevant data</li></ul>' },
{ courseCode: 'BRANCHING', order: 2, title: 'The Branching Diagram', type: 'text', content: '<h2>Visual Branching Diagram</h2><p>The Form Builder shows an SVG diagram of branching logic:</p><ul><li>Fields shown as nodes</li><li>Arrows indicate show/hide dependencies</li><li>Green arrows = "show when true"</li><li>Red arrows = "hide when true"</li><li>Hover a node to highlight its dependencies</li></ul><p>The diagram updates in real-time as you add conditions.</p>' },
{ courseCode: 'BRANCHING', order: 3, title: 'Adding Show/Hide Conditions', type: 'text', content: '<h2>Creating a Condition</h2><ol><li>Select the target field (the one to show/hide)</li><li>Click "Add Condition" in the properties panel</li><li>Choose source field (the one to evaluate)</li><li>Select operator (equals, not equals, contains, etc.)</li><li>Set the trigger value</li><li>Choose action: Show or Hide</li></ol>' },
{ courseCode: 'BRANCHING', order: 4, title: 'Operators by Field Type', type: 'text', content: '<h2>Available Operators</h2><table><tr><th>Source Field Type</th><th>Operators</th></tr><tr><td>Text</td><td>equals, not equals, contains, is empty, is not empty</td></tr><tr><td>Number</td><td>equals, >, <, >=, <=, between, is empty</td></tr><tr><td>Dropdown/Radio</td><td>equals, not equals, is one of, is empty</td></tr><tr><td>Checkbox</td><td>includes, does not include, is empty</td></tr><tr><td>Date</td><td>before, after, between, is empty</td></tr></table>' },
{ courseCode: 'BRANCHING', order: 5, title: 'Multiple Conditions (OR Logic)', type: 'text', content: '<h2>Combining Conditions</h2><p>You can add multiple conditions to a single target field:</p><ul><li>Multiple conditions use <strong>OR</strong> logic by default</li><li>Target shows if ANY condition is true</li><li>Example: Show "Other (specify)" if Drug=Other OR Route=Other</li></ul><p>For AND logic (all conditions must be true), use a formula-based condition in the Custom Rule Builder.</p>' },
{ courseCode: 'BRANCHING', order: 6, title: 'Conditional Required', type: 'text', content: '<h2>Conditional Required Fields</h2><p>Make a field required only when visible:</p><ul><li>Set "Required" = "When Visible" (not always)</li><li>Field is required only if its show condition is met</li><li>Hidden fields are automatically not required</li><li>Example: "Specify Other" is required only when "Other" is selected</li></ul>' },
{ courseCode: 'BRANCHING', order: 7, title: 'Form Linking', type: 'text', content: '<h2>Cross-Form Branching</h2><p>Link conditions across forms in the same visit:</p><ul><li>Show Form B only if Form A field X = "Yes"</li><li>Example: Show "AE Details" form only if "Any AEs?" = "Yes" on Safety form</li><li>Links use the same operator set as within-form conditions</li></ul><p>Cross-form links are configured at the visit level, not within the form builder.</p>' },
{ courseCode: 'BRANCHING', order: 8, title: 'Saving Branching with E-Signature', type: 'text', content: '<h2>Publishing Branching Changes</h2><p>Like all form modifications, branching logic changes require e-signature to publish:</p><ul><li>Draft changes are saved without signature</li><li>Publishing makes conditions active for data entry users</li><li>Version number increments on publish</li><li>Existing data is not affected retroactively</li></ul>' },
{ courseCode: 'BRANCHING', order: 9, title: 'Exercise: Create a Show/Hide Condition', type: 'interactive', content: 'Configure a branching condition.', interactiveConfig: { type: 'fill-form', instruction: 'Configure: Show "Pregnancy Details" section when "Sex" field = "Female" AND "Pregnant?" = "Yes".', data: { fields: [{ label: 'Target (field to show/hide)', type: 'text', correctAnswer: 'any', placeholder: 'Pregnancy Details section' }, { label: 'Condition 1 - Source Field', type: 'select', correctAnswer: 'Sex', options: ['Sex', 'Age', 'Weight', 'Name'] }, { label: 'Condition 1 - Value', type: 'select', correctAnswer: 'Female', options: ['Male', 'Female', 'Other'] }, { label: 'Condition 2 - Source Field', type: 'select', correctAnswer: 'Pregnant?', options: ['Sex', 'Pregnant?', 'Age', 'Smoker?'] }, { label: 'Condition 2 - Value', type: 'select', correctAnswer: 'Yes', options: ['Yes', 'No', 'Unknown'] }] }, successMessage: 'Correct! Pregnancy Details only shows for pregnant female patients.', hintMessage: 'Think about which two conditions must BOTH be true.' } },
{ courseCode: 'BRANCHING', order: 10, title: 'Knowledge Check: Branching', type: 'knowledge-check', content: 'Test branching logic knowledge.', interactiveConfig: { sectionTitle: 'Branching Logic', questions: [{ id: 'br-1', question: 'Multiple conditions on a target field use which logic by default?', type: 'multiple-choice', options: ['AND (all must be true)', 'OR (any can be true)', 'XOR (exactly one true)', 'NOT (none true)'], correctIndex: 1, explanation: 'Multiple conditions use OR logic — target shows if ANY condition is met.' }, { id: 'br-2', question: 'True or False: Hidden fields can still be required.', type: 'true-false', options: ['True', 'False'], correctIndex: 1, explanation: 'Hidden fields are automatically not required. Use "Required When Visible" for conditional requirement.' }, { id: 'br-3', question: 'Branching changes require what to publish?', type: 'multiple-choice', options: ['Manager approval email', 'E-signature', 'Waiting period of 24h', 'Nothing — auto-publishes'], correctIndex: 1, explanation: 'All form changes including branching require e-signature to publish.' }] } },
// ============ USER-MGMT (6 slides) ============
{ courseCode: 'USER-MGMT', order: 1, title: 'User Management Overview', type: 'text', content: '<h2>Managing Users</h2><p>Navigate: Admin → User Management. Admins can create, edit, deactivate users and assign roles.</p><ul><li>Users belong to an organization</li><li>Roles determine permissions (what they can see/do)</li><li>Users are assigned to specific studies and sites</li><li>Deactivated users cannot log in but records are preserved</li></ul>' },
{ courseCode: 'USER-MGMT', order: 2, title: 'Roles and Permissions', type: 'text', content: '<h2>Standard Roles</h2><table><tr><th>Role</th><th>Permissions</th></tr><tr><td>Site Coordinator</td><td>Data entry, respond to queries</td></tr><tr><td>Investigator</td><td>Review, sign forms, medical decisions</td></tr><tr><td>Monitor (CRA)</td><td>SDV, create queries, review data</td></tr><tr><td>Data Manager</td><td>Full data access, close queries, locks</td></tr><tr><td>Study Manager</td><td>Study configuration, user management</td></tr><tr><td>Admin</td><td>Everything including system settings</td></tr></table>' },
{ courseCode: 'USER-MGMT', order: 3, title: 'Creating a User', type: 'text', content: '<h2>New User Workflow</h2><ol><li>Click "+ Add User" → enter email, name, role</li><li>Assign to study(ies) and site(s)</li><li>Set temporary password or send invite email</li><li>User must change password on first login</li><li>User completes required training before access granted</li></ol><p>All user creation is audit-logged with who created the account and when.</p>' },
{ courseCode: 'USER-MGMT', order: 4, title: 'Exercise: Assign the Right Role', type: 'interactive', content: 'Match users to appropriate roles.', interactiveConfig: { type: 'match-pairs', instruction: 'Match each person to their correct system role.', data: { pairs: [{ left: 'Nurse entering patient data at site', right: 'Site Coordinator' }, { left: 'Doctor reviewing and signing forms', right: 'Investigator' }, { left: 'Sponsor rep doing remote monitoring', right: 'Monitor (CRA)' }, { left: 'Biostatistician cleaning datasets', right: 'Data Manager' }] }, successMessage: 'Correct role assignments!' } },
{ courseCode: 'USER-MGMT', order: 5, title: 'Knowledge Check: User Management', type: 'knowledge-check', content: 'Test user management knowledge.', interactiveConfig: { sectionTitle: 'User Management', questions: [{ id: 'um-1', question: 'What happens when a user is deactivated?', type: 'multiple-choice', options: ['All their data is deleted', 'They cannot log in but records are preserved', 'Their role changes to read-only', 'Nothing changes'], correctIndex: 1, explanation: 'Deactivation prevents login while preserving all audit trail entries and data.' }, { id: 'um-2', question: 'Users must complete what before getting system access?', type: 'multiple-choice', options: ['Nothing', 'Required training modules', 'A phone interview', '30-day waiting period'], correctIndex: 1, explanation: 'Required training must be completed before access is granted (regulatory requirement).' }] } },
{ courseCode: 'USER-MGMT', order: 6, title: 'Summary: User Management', type: 'text', content: '<h2>Key Takeaways</h2><ul><li>Users have roles that control all permissions</li><li>Users are assigned to specific studies and sites</li><li>Creation requires: email, name, role, study/site assignment</li><li>Training must be completed before access</li><li>Deactivation preserves records (never delete users)</li><li>All changes are audit-logged</li></ul>' },
// ============ DATA-LOCKS (6 slides) ============
{ courseCode: 'DATA-LOCKS', order: 1, title: 'What Are Data Locks?', type: 'text', content: '<h2>Data Locks</h2><p>Data locks freeze data to prevent further modification. Used at study milestones:</p><ul><li><strong>Soft Lock (Freeze):</strong> Prevents edits but can be unlocked by authorized users</li><li><strong>Hard Lock:</strong> Permanent — used for database lock at study close</li></ul><p>Locks can be applied at: field, form, visit, patient, or study level.</p>' },
{ courseCode: 'DATA-LOCKS', order: 2, title: 'Lock Levels', type: 'text', content: '<h2>Lock Granularity</h2><table><tr><th>Level</th><th>Scope</th><th>Use Case</th></tr><tr><td>Field</td><td>Single data point</td><td>Confirmed critical value</td></tr><tr><td>Form</td><td>Entire CRF</td><td>After SDV and signature</td></tr><tr><td>Visit</td><td>All forms in a visit</td><td>Visit data complete and verified</td></tr><tr><td>Patient</td><td>All data for one subject</td><td>Subject completed study</td></tr><tr><td>Study</td><td>Entire database</td><td>Database lock for analysis</td></tr></table>' },
{ courseCode: 'DATA-LOCKS', order: 3, title: 'Applying a Lock', type: 'text', content: '<h2>Lock Process</h2><ol><li>Navigate to the target (form, visit, patient, or study)</li><li>Click "Lock" or "Freeze" action button</li><li>Confirm scope (what will be locked)</li><li>Enter e-signature (username + password + reason)</li><li>Data becomes read-only immediately</li></ol><p>Prerequisites: All queries must be closed. All required forms must be signed.</p>' },
{ courseCode: 'DATA-LOCKS', order: 4, title: 'Exercise: Lock Prerequisites', type: 'interactive', content: 'Identify what must be done before locking.', interactiveConfig: { type: 'scenario', instruction: 'You want to lock Patient SITE01-005 but the system shows errors.', data: { context: 'The system reports: 2 open queries, 1 unsigned form on Visit 3, all other forms signed and verified.', choices: [{ text: 'Lock anyway — the system should allow overrides', correct: false, feedback: 'Locks require all queries closed and forms signed. No overrides allowed.' }, { text: 'Close the 2 queries and sign the unsigned form first, then lock', correct: true, feedback: 'Correct! All prerequisites must be met before locking.' }, { text: 'Delete the open queries and skip the unsigned form', correct: false, feedback: 'Queries must be properly closed (not deleted). Forms must be signed.' }] }, successMessage: 'Always resolve all open items before locking.' } },
{ courseCode: 'DATA-LOCKS', order: 5, title: 'Knowledge Check: Data Locks', type: 'knowledge-check', content: 'Test data lock knowledge.', interactiveConfig: { sectionTitle: 'Data Locks', questions: [{ id: 'dl-1', question: 'What is the difference between freeze and hard lock?', type: 'multiple-choice', options: ['No difference', 'Freeze can be undone; hard lock is permanent', 'Hard lock is faster', 'Freeze is for studies; hard lock is for patients'], correctIndex: 1, explanation: 'Freeze (soft lock) is reversible. Hard lock is permanent and used at database lock.' }, { id: 'dl-2', question: 'What must be done before locking a patient?', type: 'multiple-choice', options: ['Nothing — lock anytime', 'All queries closed and forms signed', 'Wait 30 days', 'Export data first'], correctIndex: 1, explanation: 'All queries must be closed and required forms signed before locking.' }] } },
{ courseCode: 'DATA-LOCKS', order: 6, title: 'Summary: Data Locks', type: 'text', content: '<h2>Key Takeaways</h2><ul><li>Freeze = reversible soft lock; Hard Lock = permanent</li><li>Lock levels: field, form, visit, patient, study</li><li>Prerequisites: all queries closed, forms signed</li><li>Locking requires e-signature</li><li>Database lock (study-level) used at study close for unblinding/analysis</li></ul>' },
// ============ SDV (6 slides) ============
{ courseCode: 'SDV', order: 1, title: 'What is Source Data Verification?', type: 'text', content: '<h2>SDV Overview</h2><p>Source Data Verification confirms that CRF data matches original source documents (medical records, lab reports).</p><ul><li>Required by ICH-GCP for regulatory submissions</li><li>Performed by Clinical Research Associates (CRAs/Monitors)</li><li>100% SDV or risk-based SDV depending on study plan</li><li>Verified fields are marked with a checkmark indicator</li></ul>' },
{ courseCode: 'SDV', order: 2, title: 'SDV Workflow', type: 'text', content: '<h2>SDV Process</h2><ol><li>Monitor opens patient record</li><li>Compares each CRF field against source documents</li><li>Marks fields as "Verified" (checkmark) or creates query if discrepancy found</li><li>Once all fields verified → form marked "SDV Complete"</li><li>SDV-complete forms can be frozen</li></ol>' },
{ courseCode: 'SDV', order: 3, title: 'SDV Indicators', type: 'text', content: '<h2>Visual Indicators</h2><table><tr><th>Indicator</th><th>Meaning</th></tr><tr><td>No mark</td><td>Not yet verified</td></tr><tr><td>Green checkmark</td><td>Field verified — matches source</td></tr><tr><td>Blue dot</td><td>Query created — discrepancy found</td></tr><tr><td>Purple badge (form)</td><td>Form fully SDV-complete</td></tr></table><p>Progress bar shows % of fields verified per form/visit.</p>' },
{ courseCode: 'SDV', order: 4, title: 'Exercise: SDV Decisions', type: 'interactive', content: 'Decide the correct SDV action for each scenario.', interactiveConfig: { type: 'match-pairs', instruction: 'Match each finding to the correct SDV action.', data: { pairs: [{ left: 'CRF shows BP 120/80, source doc shows 120/80', right: 'Mark as Verified' }, { left: 'CRF shows weight 75kg, source doc shows 57kg', right: 'Create a Query' }, { left: 'CRF date is 15-JAN-2024, source doc matches', right: 'Mark as Verified' }, { left: 'CRF field is blank but source doc has a value', right: 'Create a Query' }] }, successMessage: 'Correct! Verify when matching, query when discrepant.' } },
{ courseCode: 'SDV', order: 5, title: 'Knowledge Check: SDV', type: 'knowledge-check', content: 'Test SDV knowledge.', interactiveConfig: { sectionTitle: 'Source Data Verification', questions: [{ id: 'sdv-1', question: 'Who performs SDV?', type: 'multiple-choice', options: ['Site coordinators', 'Patients', 'CRAs/Monitors', 'Data entry clerks'], correctIndex: 2, explanation: 'Clinical Research Associates (Monitors) perform SDV during monitoring visits.' }, { id: 'sdv-2', question: 'After 100% SDV, a form can be:', type: 'multiple-choice', options: ['Deleted', 'Frozen', 'Transferred', 'Duplicated'], correctIndex: 1, explanation: 'SDV-complete forms can be frozen to prevent further changes.' }] } },
{ courseCode: 'SDV', order: 6, title: 'Summary: SDV', type: 'text', content: '<h2>Key Takeaways</h2><ul><li>SDV = comparing CRF data to source documents</li><li>Performed by monitors (CRAs)</li><li>Mark verified (match) or create query (discrepancy)</li><li>Progress tracked per field, form, visit, patient</li><li>SDV-complete forms can be frozen</li><li>Required by ICH-GCP for regulatory compliance</li></ul>' },
// ============ WORKFLOW (6 slides) ============
{ courseCode: 'WORKFLOW', order: 1, title: 'Workflow & Tasks Overview', type: 'text', content: '<h2>Task Management</h2><p>The workflow system routes tasks to the right people at the right time.</p><ul><li>Navigate: Sidebar → My Tasks</li><li>Tasks auto-generated from: queries, signatures needed, overdue visits, SDV assignments</li><li>Priority levels: Urgent, High, Normal, Low</li><li>Tasks show due date and assignee</li></ul>' },
{ courseCode: 'WORKFLOW', order: 2, title: 'Task Types', type: 'text', content: '<h2>Common Task Types</h2><table><tr><th>Task</th><th>Assigned To</th><th>Trigger</th></tr><tr><td>Respond to Query</td><td>Site Coordinator</td><td>New query created on their patient</td></tr><tr><td>Review Query Response</td><td>Monitor/DM</td><td>Site responds to query</td></tr><tr><td>Sign Form</td><td>Investigator</td><td>Form submitted, needs PI signature</td></tr><tr><td>Complete Overdue Form</td><td>Site Coordinator</td><td>Visit window passed</td></tr><tr><td>Perform SDV</td><td>Monitor</td><td>New data entered, SDV plan triggered</td></tr></table>' },
{ courseCode: 'WORKFLOW', order: 3, title: 'Working with Tasks', type: 'text', content: '<h2>Task Actions</h2><ul><li><strong>Click task</strong> → navigates to the relevant form/query/patient</li><li><strong>Complete:</strong> Mark done after performing the action</li><li><strong>Reassign:</strong> Transfer to another user (with reason)</li><li><strong>Snooze:</strong> Defer for a set period</li><li><strong>Filters:</strong> By type, priority, due date, study</li></ul><p>Overdue tasks appear in red. Completed tasks move to history.</p>' },
{ courseCode: 'WORKFLOW', order: 4, title: 'Exercise: Task Prioritization', type: 'interactive', content: 'Prioritize tasks correctly.', interactiveConfig: { type: 'order-steps', instruction: 'Order these tasks by priority (most urgent first).', data: { steps: [{ id: 's1', text: 'Respond to critical safety query (1 day overdue)' }, { id: 's2', text: 'Sign completed Adverse Event form' }, { id: 's3', text: 'Complete routine Week 4 visit form (due in 2 days)' }, { id: 's4', text: 'Review minor data clarification query' }], correctOrder: ['s1', 's2', 's3', 's4'] }, successMessage: 'Correct! Safety items first, then signatures, then routine tasks.' } },
{ courseCode: 'WORKFLOW', order: 5, title: 'Knowledge Check: Workflow', type: 'knowledge-check', content: 'Test workflow knowledge.', interactiveConfig: { sectionTitle: 'Workflow & Tasks', questions: [{ id: 'wf-1', question: 'Tasks are auto-generated from:', type: 'multiple-choice', options: ['User requests only', 'Queries, signatures, overdue visits, SDV assignments', 'Random system scheduling', 'Monthly batch processing'], correctIndex: 1, explanation: 'Tasks auto-generate from system events like queries, needed signatures, and overdue items.' }, { id: 'wf-2', question: 'Overdue tasks appear in what color?', type: 'multiple-choice', options: ['Green', 'Blue', 'Red', 'Gray'], correctIndex: 2, explanation: 'Red indicates overdue/urgent items requiring immediate attention.' }] } },
{ courseCode: 'WORKFLOW', order: 6, title: 'Summary: Workflow', type: 'text', content: '<h2>Key Takeaways</h2><ul><li>My Tasks = personal work queue</li><li>Tasks auto-generated from system events</li><li>Click task to navigate directly to the work item</li><li>Priority: safety/urgent first, then routine</li><li>Reassign or snooze if needed (with reason)</li><li>Overdue tasks escalate automatically</li></ul>' },
// ============ RANDOMIZE (8 slides) ============
{ courseCode: 'RANDOMIZE', order: 1, title: 'Randomization Overview', type: 'text', content: '<h2>What is Randomization?</h2><p>Randomization assigns patients to treatment groups in an unbiased manner.</p><ul><li>Eliminates selection bias</li><li>Ensures balanced groups</li><li>Treatment assignment is blinded (investigators do not know group)</li><li>System manages the randomization list</li></ul>' },
{ courseCode: 'RANDOMIZE', order: 2, title: 'Randomization Methods', type: 'text', content: '<h2>Supported Methods</h2><table><tr><th>Method</th><th>Description</th></tr><tr><td>Simple</td><td>Pure random assignment (coin flip)</td></tr><tr><td>Block</td><td>Balanced within blocks (e.g., blocks of 4)</td></tr><tr><td>Stratified</td><td>Balanced within strata (age group, site, sex)</td></tr><tr><td>Minimization</td><td>Dynamic balancing across multiple factors</td></tr></table><p>Method is defined during study setup (Tab 7: Randomization).</p>' },
{ courseCode: 'RANDOMIZE', order: 3, title: 'Randomization Configuration', type: 'text', content: '<h2>Setup</h2><ul><li><strong>Treatment arms:</strong> Define groups (Drug A, Drug B, Placebo)</li><li><strong>Ratio:</strong> Allocation ratio (1:1, 2:1, etc.)</li><li><strong>Stratification factors:</strong> Site, age group, sex, severity</li><li><strong>Block size:</strong> Number per block (4, 6, 8 — or variable)</li><li><strong>Seed:</strong> Random seed for reproducibility</li></ul><p>Configuration is locked after first randomization occurs.</p>' },
{ courseCode: 'RANDOMIZE', order: 4, title: 'Performing Randomization', type: 'text', content: '<h2>Randomizing a Patient</h2><ol><li>Open patient record → Actions → Randomize</li><li>Confirm eligibility criteria are met</li><li>Enter stratification values if applicable</li><li>Click "Randomize" → system assigns treatment group</li><li>E-sign to confirm</li></ol><p>Treatment assignment is masked — you see "Group A/B" not actual drug names (if blinded).</p>' },
{ courseCode: 'RANDOMIZE', order: 5, title: 'Unblinding', type: 'text', content: '<h2>Emergency Unblinding</h2><p>In medical emergencies, the investigator can unblind a single patient:</p><ul><li>Requires emergency justification</li><li>E-signature with specific reason</li><li>Creates permanent audit trail entry</li><li>Notifies sponsor immediately</li><li>Patient remains in study unless withdrawn</li></ul><p>Routine unblinding occurs only at database lock / study completion.</p>' },
{ courseCode: 'RANDOMIZE', order: 6, title: 'Exercise: Randomization Steps', type: 'interactive', content: 'Order the randomization workflow.', interactiveConfig: { type: 'order-steps', instruction: 'Put the randomization steps in correct order.', data: { steps: [{ id: 's1', text: 'Confirm patient meets all eligibility criteria' }, { id: 's2', text: 'Navigate to patient → Actions → Randomize' }, { id: 's3', text: 'Enter stratification factors (site, age group)' }, { id: 's4', text: 'Click Randomize — system assigns treatment group' }, { id: 's5', text: 'E-sign to confirm randomization' }], correctOrder: ['s1', 's2', 's3', 's4', 's5'] }, successMessage: 'Correct randomization workflow!' } },
{ courseCode: 'RANDOMIZE', order: 7, title: 'Knowledge Check: Randomization', type: 'knowledge-check', content: 'Test randomization knowledge.', interactiveConfig: { sectionTitle: 'Randomization', questions: [{ id: 'rz-1', question: 'Block randomization ensures:', type: 'multiple-choice', options: ['Patients are blocked from enrolling', 'Treatment groups are balanced within blocks', 'Only one site can randomize at a time', 'Randomization happens in batches'], correctIndex: 1, explanation: 'Block randomization ensures balanced groups within each block (e.g., 2A + 2B in a block of 4).' }, { id: 'rz-2', question: 'Emergency unblinding requires:', type: 'multiple-choice', options: ['Nothing special', 'Sponsor approval first', 'E-signature with emergency justification', 'Waiting 24 hours'], correctIndex: 2, explanation: 'Emergency unblinding needs e-signature with documented medical justification.' }] } },
{ courseCode: 'RANDOMIZE', order: 8, title: 'Summary: Randomization', type: 'text', content: '<h2>Key Takeaways</h2><ul><li>Methods: Simple, Block, Stratified, Minimization</li><li>Configure during study setup (locked after first use)</li><li>Confirm eligibility before randomizing</li><li>Treatment group is blinded (Group A/B)</li><li>Emergency unblinding: documented, e-signed, audited</li><li>Full unblinding only at database lock</li></ul>' },
// ============ LOGIN-NAV (3 slides) ============
{ courseCode: 'LOGIN-NAV', order: 1, title: 'Signing In', type: 'text', content: '<h2>Login</h2><img src="assets/sop-screenshots/sop-032/01_login.png" alt="Login Page"><ul><li>Enter email and password at the login page</li><li>Passwords: 12+ chars, mixed case, number, special character</li><li>Account locks after 5 failed attempts — contact admin</li><li>Passwords expire every 90 days</li></ul>' },
{ courseCode: 'LOGIN-NAV', order: 2, title: 'Sidebar Navigation', type: 'text', content: '<h2>Sidebar Sections</h2><table><tr><th>Section</th><th>Items</th></tr><tr><td>Main</td><td>Dashboard, My Tasks</td></tr><tr><td>Clinical</td><td>Patients, Forms, Queries, Events</td></tr><tr><td>Admin</td><td>Users, Studies, Settings (admin roles only)</td></tr></table><p>Tip: Use Ctrl+K for global search across all sections. Click sidebar items to expand/collapse.</p>' },
{ courseCode: 'LOGIN-NAV', order: 3, title: 'Knowledge Check: Login & Navigation', type: 'knowledge-check', content: 'Quick check.', interactiveConfig: { sectionTitle: 'Login & Navigation', questions: [{ id: 'ln-1', question: 'Account locks after how many failed attempts?', type: 'multiple-choice', options: ['3', '5', '10', 'Never'], correctIndex: 1, explanation: '5 failed attempts triggers account lockout.' }, { id: 'ln-2', question: 'Where do you find Queries in the sidebar?', type: 'multiple-choice', options: ['Main section', 'Clinical section', 'Admin section', 'Profile menu'], correctIndex: 1, explanation: 'Queries is under the Clinical section.' }] } },
// ============ E-SIGN (4 slides) ============
{ courseCode: 'E-SIGN', order: 1, title: 'What is E-Signature?', type: 'text', content: '<h2>Electronic Signatures</h2><p>Per 21 CFR Part 11, e-signatures are legally equivalent to handwritten signatures. They provide non-repudiation — proof that a specific person performed an action at a specific time.</p><ul><li>Legally binding in regulated clinical trials</li><li>Tied to a unique user account</li><li>Cannot be shared, delegated, or forged</li></ul>' },
{ courseCode: 'E-SIGN', order: 2, title: 'When E-Signatures Are Required', type: 'text', content: '<h2>Signature Triggers</h2><ul><li>Submitting a completed CRF</li><li>Publishing a form design</li><li>Locking/freezing data</li><li>Closing queries</li><li>Creating/modifying validation rules</li><li>Enrolling or withdrawing patients</li><li>Any action with regulatory significance</li></ul>' },
{ courseCode: 'E-SIGN', order: 3, title: 'The 3-Step Process', type: 'text', content: '<h2>Signing Process</h2><ol><li><strong>Authenticate:</strong> Enter your username and password</li><li><strong>Declare meaning:</strong> Select reason (e.g., "I have reviewed this data and it is accurate")</li><li><strong>Confirm:</strong> Click Sign — creates immutable audit record with timestamp</li></ol><p>Failed authentication cancels the signature. You get 3 attempts before lockout.</p>' },
{ courseCode: 'E-SIGN', order: 4, title: 'Knowledge Check: E-Signatures', type: 'knowledge-check', content: 'Test e-signature knowledge.', interactiveConfig: { sectionTitle: 'E-Signatures', questions: [{ id: 'es-1', question: 'E-signatures require:', type: 'multiple-choice', options: ['Just a click', 'Username + password + reason', 'Fingerprint scan', 'Manager co-signature'], correctIndex: 1, explanation: 'Three components: authenticate (user+pass), declare meaning (reason), confirm.' }, { id: 'es-2', question: 'True or False: E-signatures can be delegated to another user.', type: 'true-false', options: ['True', 'False'], correctIndex: 1, explanation: 'E-signatures are non-transferable — each user signs with their own credentials only.' }] } },
// ============ DATA-EXPORT (3 slides) ============
{ courseCode: 'DATA-EXPORT', order: 1, title: 'Export Formats', type: 'text', content: '<h2>Available Export Formats</h2><table><tr><th>Format</th><th>Use Case</th></tr><tr><td>CSV</td><td>General analysis, Excel, SAS import</td></tr><tr><td>SAS (.sas7bdat)</td><td>Direct SAS analysis</td></tr><tr><td>CDISC ODM (XML)</td><td>Regulatory submission, archive</td></tr><tr><td>PDF</td><td>Blank/annotated CRFs, audit reports</td></tr></table><p>All exports are audit-logged with who exported, what scope, and when.</p>' },
{ courseCode: 'DATA-EXPORT', order: 2, title: 'How to Export', type: 'text', content: '<h2>Export Process</h2><ol><li>Navigate: Admin → Data Export (or Study → Export)</li><li>Select scope: entire study, specific forms, date range, or patients</li><li>Choose format (CSV, SAS, ODM, PDF)</li><li>Click Export → file downloads or queues for large datasets</li><li>E-signature required for production data exports</li></ol>' },
{ courseCode: 'DATA-EXPORT', order: 3, title: 'Knowledge Check: Export', type: 'knowledge-check', content: 'Test export knowledge.', interactiveConfig: { sectionTitle: 'Data Export', questions: [{ id: 'dx-1', question: 'Which format is used for regulatory submissions?', type: 'multiple-choice', options: ['CSV', 'Excel', 'CDISC ODM (XML)', 'JSON'], correctIndex: 2, explanation: 'CDISC ODM XML is the standard format for regulatory archive and submission.' }, { id: 'dx-2', question: 'True or False: Data exports are audit-logged.', type: 'true-false', options: ['True', 'False'], correctIndex: 0, explanation: 'All exports are logged with who, what, and when for regulatory traceability.' }] } },
// ============ REPORTS (3 slides) ============
{ courseCode: 'REPORTS', order: 1, title: 'Finding Reports', type: 'text', content: '<h2>Reports Location</h2><p>Navigate: Sidebar → Reports (or Dashboard → click any metric card).</p><ul><li>Reports are role-filtered — you see only what your role permits</li><li>Reports update in real-time</li><li>All reports can be exported to PDF or CSV</li></ul>' },
{ courseCode: 'REPORTS', order: 2, title: 'Available Report Types', type: 'text', content: '<h2>Report Categories</h2><table><tr><th>Category</th><th>Reports</th></tr><tr><td>Enrollment</td><td>Screening log, enrollment curve, site performance</td></tr><tr><td>Data Quality</td><td>Query aging, missing data, validation failures</td></tr><tr><td>Compliance</td><td>SDV progress, signature status, overdue visits</td></tr><tr><td>Safety</td><td>AE listings, SAE summary, concomitant meds</td></tr><tr><td>Audit</td><td>Audit trail reports, user activity log</td></tr></table>' },
{ courseCode: 'REPORTS', order: 3, title: 'Knowledge Check: Reports', type: 'knowledge-check', content: 'Test reports knowledge.', interactiveConfig: { sectionTitle: 'Reports', questions: [{ id: 'rp-1', question: 'Reports are filtered by:', type: 'multiple-choice', options: ['Browser type', 'User role', 'Time of day', 'Alphabetical order'], correctIndex: 1, explanation: 'Role-based filtering ensures users only see reports relevant to their permissions.' }, { id: 'rp-2', question: 'Query aging report falls under which category?', type: 'multiple-choice', options: ['Enrollment', 'Data Quality', 'Safety', 'Compliance'], correctIndex: 1, explanation: 'Query aging is a Data Quality report showing how long queries remain open.' }] } },
// ============ GCP-101 (6 slides) ============
{ courseCode: 'GCP-101', order: 1, title: 'ICH E6 Good Clinical Practice', type: 'text', content: '<h2>What is GCP?</h2><p>ICH E6(R2) Good Clinical Practice is the international ethical and scientific quality standard for designing, conducting, recording, and reporting clinical trials.</p><ul><li>Protects patient rights, safety, and well-being</li><li>Ensures data credibility and accuracy</li><li>Harmonized across US (FDA), EU (EMA), Japan (PMDA)</li><li>Compliance is legally required for drug approval</li></ul>' },
{ courseCode: 'GCP-101', order: 2, title: 'Investigator Duties', type: 'text', content: '<h2>Key Investigator Responsibilities</h2><ul><li>Qualified by education, training, and experience</li><li>Adequate resources (staff, facilities, time)</li><li>Obtain informed consent before any study procedure</li><li>Ensure protocol compliance at the site</li><li>Report adverse events promptly</li><li>Maintain adequate and accurate source documents</li><li>Allow monitoring, auditing, and regulatory inspection</li></ul>' },
{ courseCode: 'GCP-101', order: 3, title: 'Informed Consent', type: 'text', content: '<h2>Informed Consent Requirements</h2><ul><li>Written in language the patient understands</li><li>Describes: purpose, procedures, risks, benefits, alternatives</li><li>Voluntary — no coercion or undue influence</li><li>Patient can withdraw at any time without penalty</li><li>Signed and dated by patient AND person obtaining consent</li><li>Copy provided to patient; original filed in site records</li></ul>' },
{ courseCode: 'GCP-101', order: 4, title: 'Essential Documents', type: 'text', content: '<h2>Essential Documents</h2><p>Must be maintained throughout the trial:</p><table><tr><th>Phase</th><th>Key Documents</th></tr><tr><td>Before trial</td><td>Protocol, IB, informed consent, IRB approval, CVs, lab normals</td></tr><tr><td>During trial</td><td>Signed ICFs, CRFs, AE reports, monitoring reports, deviations</td></tr><tr><td>After trial</td><td>Final report, audit certificates, regulatory correspondence</td></tr></table>' },
{ courseCode: 'GCP-101', order: 5, title: 'Record Retention', type: 'text', content: '<h2>Record Retention</h2><ul><li>Retain essential documents for minimum period per regulation</li><li>FDA: 2 years after drug approval (or investigation discontinuation)</li><li>EU: 25 years after trial completion (per country)</li><li>Do NOT destroy without sponsor notification</li><li>Electronic records must remain accessible and readable</li></ul>' },
{ courseCode: 'GCP-101', order: 6, title: 'Knowledge Check: GCP', type: 'knowledge-check', content: 'Test GCP knowledge.', interactiveConfig: { sectionTitle: 'Good Clinical Practice', questions: [{ id: 'gcp-1', question: 'Informed consent must be:', type: 'multiple-choice', options: ['Verbal only', 'Written, signed, dated, and voluntary', 'Obtained after procedures start', 'Optional for healthy volunteers'], correctIndex: 1, explanation: 'ICH-GCP requires written, signed, dated, voluntary informed consent before any study procedure.' }, { id: 'gcp-2', question: 'True or False: Patients can withdraw from a trial at any time.', type: 'true-false', options: ['True', 'False'], correctIndex: 0, explanation: 'Patients have the right to withdraw at any time without penalty to their care.' }] } },
// ============ CFR11-101 (6 slides) ============
{ courseCode: 'CFR11-101', order: 1, title: 'What 21 CFR Part 11 Covers', type: 'text', content: '<h2>21 CFR Part 11</h2><p>FDA regulation governing electronic records and electronic signatures in regulated industries.</p><ul><li>Applies to: any records required by FDA predicate rules</li><li>Purpose: ensure electronic records are as trustworthy as paper</li><li>Covers: creation, modification, maintenance, archival, retrieval, transmission</li><li>Non-compliance can invalidate study data</li></ul>' },
{ courseCode: 'CFR11-101', order: 2, title: 'Electronic Records Requirements', type: 'text', content: '<h2>Record Requirements</h2><ul><li><strong>Validation:</strong> System must be validated for intended use</li><li><strong>Record generation:</strong> Accurate, complete copies must be producible</li><li><strong>Record protection:</strong> Secure from unauthorized alteration/deletion</li><li><strong>Retrieval:</strong> Records must be retrievable throughout retention period</li><li><strong>Limiting access:</strong> Only authorized individuals can use the system</li></ul>' },
{ courseCode: 'CFR11-101', order: 3, title: 'E-Signature Requirements', type: 'text', content: '<h2>Signature Requirements</h2><ul><li>Unique to one individual — never shared</li><li>Identity verified before issuance</li><li>Contain: printed name, date/time, meaning (review, approval, authorship)</li><li>Linked to the record — cannot be separated or copied</li><li>Non-biometric signatures: two distinct components (e.g., user ID + password)</li></ul>' },
{ courseCode: 'CFR11-101', order: 4, title: 'Audit Trails', type: 'text', content: '<h2>Audit Trail Requirements</h2><ul><li>Computer-generated, time-stamped record of all changes</li><li>Records: who, what, when, previous value, new value</li><li>Cannot be modified or disabled by users</li><li>Retained for the same period as the underlying record</li><li>Available for FDA inspection</li></ul><p>AccuraTrial implements this via automatic audit logging on every data mutation.</p>' },
{ courseCode: 'CFR11-101', order: 5, title: 'System Validation & Access Controls', type: 'text', content: '<h2>Additional Requirements</h2><ul><li><strong>System validation:</strong> Documented testing proving system works as intended</li><li><strong>Access controls:</strong> Role-based, minimum necessary access</li><li><strong>Operational checks:</strong> Enforce sequencing (e.g., steps in order)</li><li><strong>Authority checks:</strong> Verify user authorized for the specific action</li><li><strong>Device checks:</strong> Determine validity of data source</li></ul>' },
{ courseCode: 'CFR11-101', order: 6, title: 'Knowledge Check: 21 CFR Part 11', type: 'knowledge-check', content: 'Test Part 11 knowledge.', interactiveConfig: { sectionTitle: '21 CFR Part 11', questions: [{ id: 'cfr-1', question: 'Audit trails must be:', type: 'multiple-choice', options: ['User-editable', 'Computer-generated and unmodifiable', 'Optional for low-risk data', 'Deleted after 1 year'], correctIndex: 1, explanation: 'Audit trails must be computer-generated, time-stamped, and cannot be modified by users.' }, { id: 'cfr-2', question: 'E-signatures must contain:', type: 'multiple-choice', options: ['Just a password', 'Name, date/time, and meaning of signature', 'A scanned image', 'Only the user ID'], correctIndex: 1, explanation: 'E-signatures must include printed name, date/time, and meaning (review, approval, etc.).' }] } },
// ============ HIPAA-101 (6 slides) ============
{ courseCode: 'HIPAA-101', order: 1, title: 'What is PHI?', type: 'text', content: '<h2>Protected Health Information</h2><p>PHI is any individually identifiable health information created or maintained by a covered entity.</p><ul><li>Relates to: past, present, or future health condition, treatment, or payment</li><li>Identifies (or could identify) a specific individual</li><li>Transmitted or maintained in any form (electronic, paper, oral)</li><li>ePHI = electronic PHI (what EDC systems handle)</li></ul>' },
{ courseCode: 'HIPAA-101', order: 2, title: '18 HIPAA Identifiers', type: 'text', content: '<h2>18 Identifiers That Make Data PHI</h2><table><tr><td>1. Name</td><td>7. Phone/Fax</td><td>13. MRN</td></tr><tr><td>2. Address (below state)</td><td>8. Email</td><td>14. Health plan #</td></tr><tr><td>3. Dates (except year)</td><td>9. SSN</td><td>15. Account #</td></tr><tr><td>4. Age >89</td><td>10. Medical record #</td><td>16. Certificate/license #</td></tr><tr><td>5. Phone</td><td>11. Device ID</td><td>17. Vehicle ID</td></tr><tr><td>6. Geographic (zip)</td><td>12. URL/IP</td><td>18. Biometric/Photo</td></tr></table><p>In EDC: use Subject IDs, not real names. Mark PHI fields appropriately.</p>' },
{ courseCode: 'HIPAA-101', order: 3, title: 'Minimum Necessary Standard', type: 'text', content: '<h2>Minimum Necessary</h2><p>Only access, use, or disclose the minimum PHI needed for the task:</p><ul><li>Role-based access controls enforce this in AccuraTrial</li><li>Only see patients assigned to your site</li><li>Only see data relevant to your role</li><li>Do not access records out of curiosity</li><li>All access is logged and auditable</li></ul>' },
{ courseCode: 'HIPAA-101', order: 4, title: 'Breach Notification', type: 'text', content: '<h2>Breach Rules</h2><ul><li><strong>Breach:</strong> Unauthorized acquisition, access, use, or disclosure of PHI</li><li>Must notify: affected individuals within 60 days</li><li>Must notify: HHS (immediately if >500 individuals)</li><li>Must notify: Media (if >500 individuals in a state)</li><li>Document the breach, remediation steps, and prevention measures</li></ul>' },
{ courseCode: 'HIPAA-101', order: 5, title: 'Research Exceptions', type: 'text', content: '<h2>HIPAA and Research</h2><ul><li><strong>Authorization:</strong> Patient signs HIPAA authorization allowing PHI use in research</li><li><strong>Waiver:</strong> IRB can waive authorization if criteria met (minimal risk, impractical to obtain)</li><li><strong>De-identified data:</strong> Not subject to HIPAA (all 18 identifiers removed)</li><li><strong>Limited dataset:</strong> Some identifiers removed + data use agreement</li></ul><p>AccuraTrial supports de-identification through Subject ID and PHI field masking.</p>' },
{ courseCode: 'HIPAA-101', order: 6, title: 'Knowledge Check: HIPAA', type: 'knowledge-check', content: 'Test HIPAA knowledge.', interactiveConfig: { sectionTitle: 'HIPAA', questions: [{ id: 'hip-1', question: 'How many HIPAA identifiers exist?', type: 'multiple-choice', options: ['8', '12', '18', '25'], correctIndex: 2, explanation: 'There are 18 identifiers that make health information individually identifiable (PHI).' }, { id: 'hip-2', question: 'Minimum necessary means:', type: 'multiple-choice', options: ['Use as much data as possible', 'Only access the minimum PHI needed for your task', 'Minimum security is sufficient', 'PHI can be shared freely within the organization'], correctIndex: 1, explanation: 'Only access, use, or disclose the minimum amount of PHI required for the specific task.' }] } },
];
